func.func @main(%idx: tensor<5xi32>) -> tensor<5x8xf32> {
  %c0 = constant dense<0> : tensor<i32>
  %c8 = constant dense<8> : tensor<i32>
  %one = constant dense<1.0 : f32> : tensor<f32>
  %zero = constant dense<0.0 : f32> : tensor<f32>

  // Create a tensor of shape <8> with values [0, 1, 2, 3, 4, 5, 6, 7]
  %iota = "stablehlo.iota"() {iota_dimension = 0 : i64} : () -> tensor<8xi32>

  // Broadcast idx (shape <5>) to shape <5x8>
  %idx_broadcast = "stablehlo.broadcast_in_dim"(%idx) {broadcast_dimensions = array<i64: 1>} : (tensor<5xi32>) -> tensor<5x8xi32>

  // Broadcast iota (shape <8>) to shape <5x8>
  %iota_broadcast = "stablehlo.broadcast_in_dim"(%iota) {broadcast_dimensions = array<i64: 0>} : (tensor<8xi32>) -> tensor<5x8xi32>

  // Compare idx_broadcast and iota_broadcast for equality
  %cmp = "stablehlo.compare"(%idx_broadcast, %iota_broadcast) {
    comparison_direction = #stablehlo<comparison_direction EQ>,
    compare_type = #stablehlo<comparison_type INT>
  } : (tensor<5x8xi32>, tensor<5x8xi32>) -> tensor<5x8xi1>

  // Convert boolean comparison result to float: 1.0 for true, 0.0 for false
  %pred_float = "stablehlo.select"(%cmp, %one, %zero) : (tensor<5x8xi1>, tensor<f32>, tensor<f32>) -> tensor<5x8xf32>

  // For rows where idx[n] outside 0..7, set entire row to zeros
  // Create a mask for valid idx values: (idx >= 0) & (idx < 8)
  %cmp_ge_zero = "stablehlo.compare"(%idx, %c0) {
    comparison_direction = #stablehlo<comparison_direction GE>,
    compare_type = #stablehlo<comparison_type INT>
  } : (tensor<5xi32>, tensor<i32>) -> tensor<5xi1>

  %cmp_lt_eight = "stablehlo.compare"(%idx, %c8) {
    comparison_direction = #stablehlo<comparison_direction LT>,
    compare_type = #stablehlo<comparison_type INT>
  } : (tensor<5xi32>, tensor<i32>) -> tensor<5xi1>

  %valid_mask = "stablehlo.select"(%cmp_ge_zero, %one, %zero) : (tensor<5xi1>, tensor<f32>, tensor<f32>) -> tensor<5xf32>
  %valid_mask_int = "stablehlo.compare"(%valid_mask, %zero) {
    comparison_direction = #stablehlo<comparison_direction NE>,
    compare_type = #stablehlo<comparison_type FLOAT>
  } : (tensor<5xf32>, tensor<f32>) -> tensor<5xi1>

  // Expand valid_mask to shape <5x8> for masking the output
  %mask_broadcast = "stablehlo.broadcast_in_dim"(%valid_mask_int) {broadcast_dimensions = array<i64: 1>} : (tensor<5xi1>) -> tensor<5x8xi1>

  // Convert mask to float: 1.0 for valid, 0.0 for invalid
  %mask_float = "stablehlo.select"(%mask_broadcast, %one, %zero) : (tensor<5x8xi1>, tensor<f32>, tensor<f32>) -> tensor<5x8xf32>

  // Final output: element-wise multiply the comparison result with the mask
  %out = "stablehlo.compare"(%pred_float, %zero) {
    comparison_direction = #stablehlo<comparison_direction NE>,
    compare_type = #stablehlo<comparison_type FLOAT>
  } : (tensor<5x8xf32>, tensor<f32>) -> tensor<5x8xf32>

  // Alternatively, directly multiply the boolean mask (converted to float) with 1.0 or 0.0
  // But since we already have the comparison result as float, and mask as float, multiply:
  %result = "stablehlo.select"(%mask_float, %pred_float, %zero) : (tensor<5x8xf32>, tensor<5x8xf32>, tensor<5x8xf32>) -> tensor<5x8xf32>

  return %result : tensor<5x8xf32>
}
