// StableHLO program implementing the described model forward pass
module {
  func.func @main(
    %arg0: tensor<6x1x1xf32>,             // multiplier
    %arg1: tensor<6x6x3x3xf32>,           // conv.weight
    %arg2: tensor<6xf32>,                  // conv.bias
    %arg3: tensor<6x6x7x7xf32>             // input
  ) -> tensor<6x6x5x5xf32> {
    // Step 1: Reshape conv.weight from [6,6,3,3] to [6,6,3,3] (already in shape)
    // No reshape needed for weight

    // Step 2: Perform convolution
    %conv_result = "chlo.convolution"(%arg3, %arg1)
      {window_strides = dense<[1, 1]>, 
       padding = dense<[0, 0, 0, 0]>, 
       lhs_dilation = dense<[1, 1]>, 
       rhs_dilation = dense<[1, 1]>, 
       window_reversal = dense<[]>, 
       feature_group_count = 1 : i32} : (tensor<6x6x7x7xf32>, tensor<6x6x3x3xf32>) -> tensor<6x6x5x5xf32>

    // Step 3: Broadcast multiplier to match conv output shape [6,6,5,5]
    // multiplier shape: [6,1,1], need to broadcast to [6,6,5,5]
    %multiplier_bcast = "chlo.broadcast_in_dim"(%arg0, dense<[0, 1, 2, 3]>, dense<[1, 6, 5, 5]>) : (tensor<6x1x1xf32>, tensor<4xi64>, tensor<4xi64>) -> tensor<6x6x5x5xf32>

    // Step 4: Element-wise multiply conv result by broadcasted multiplier
    %mul = "chlo.multiply"(%conv_result, %multiplier_bcast) : (tensor<6x6x5x5xf32>, tensor<6x6x5x5xf32>) -> tensor<6x6x5x5xf32>

    // Step 5: Apply LeakyReLU
    %leaky_relu = "chlo.leaky_relu"(%mul) {alpha = 0.01} : (tensor<6x6x5x5xf32>) -> tensor<6x6x5x5xf32>

    // Step 6: Apply GELU (approximate with erf-based formula)
    // GELU(x) ≈ 0.5 * x * (1 + erf(x / sqrt(2)))
    // Compute x / sqrt(2)
    %sqrt2 = "chlo.constant"() {value = dense<f32>({1.41421356237})} : () -> tensor<f32>
    %x_div_sqrt2 = "chlo.divide"(%leaky_relu, %sqrt2) : (tensor<6x6x5x5xf32>, tensor<f32>) -> tensor<6x6x5x5xf32>

    // Compute erf(x / sqrt(2))
    %erf_x = "chlo.erf"(%x_div_sqrt2) : (tensor<6x6x5x5xf32>) -> tensor<6x6x5x5xf32>

    // Compute 1 + erf(...)
    %one = "chlo.constant"() {value = dense<f32>({1.0})} : () -> tensor<f32>
    %one_plus_erf = "chlo.add"(%one, %erf_x) : (tensor<f32>, tensor<6x6x5x5xf32>) -> tensor<6x6x5x5xf32>

    // Compute 0.5 * x * (1 + erf(...))
    %half = "chlo.constant"() {value = dense<f32>({0.5})} : () -> tensor<f32>
    %gelu = "chlo.multiply"(%half, %leaky_relu) : (tensor<f32>, tensor<6x6x5x5xf32>) -> tensor<6x6x5x5xf32>
    %gelu_final = "chlo.multiply"(%gelu, %one_plus_erf) : (tensor<6x6x5x5xf32>, tensor<6x6x5x5xf32>) -> tensor<6x6x5x5xf32>

    // Return the final tensor
    return %gelu_final : tensor<6x6x5x5xf32>
  }
