    // divide by batch size to get variance
    %var = "stablehlo.divide"(%var_sum, %batch_size_b) : (tensor<7xf32>, tensor<7xf32>) -> tensor<7xf32>
    // reshape variance to (1,7)
    %var_reshaped = "stablehlo.broadcast_in_dim"(%var) {broadcast_dimensions = array<i64: 0>} : (tensor<7xf32>) -> tensor<1x7xf32>
    // broadcast variance to shape (6,7)
    %var_broadcast = "stablehlo.broadcast_in_dim"(%var_reshaped) {broadcast_dimensions = array<i64: 0>} : (tensor<1x7xf32>) -> tensor<6x7xf32>
