    %bn_weight_b = "stablehlo.broadcast_in_dim"(%arg3) {broadcast_dimensions = array<i64: 0>} : (tensor<7xf32>) -> tensor<6x7xf32>
    %scaled = "stablehlo.multiply"(%x_norm_final, %bn_weight_b) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

