      // kernel output channels: 0
      // kernel input channels: 1
      // kernel spatial dimensions: 2, 3, 4
    // Set feature group count to 1
    %feature_group_count = 1 : i64

    // Perform the convolution
    %conv_result = "stablehlo.convolution"(%arg1, %arg0)
      {
        window_strides = %window_strides,
        padding = %padding,
        lhs_dilation = %lhs_dilation,
        rhs_dilation = %rhs_dilation,
