    %bmm_weight = %arg0 : tensor<7x7xf32>
    %bmm_bias = %arg1 : tensor<7xf32>

    // Inputs
    %x_input = %arg2 : tensor<6x7xf32>
    %y_input = %arg3 : tensor<6x7xf32>

    // Step 1: matrix multiply x_input with bmm_weight
    // "stablehlo.dot_general" with batch dims empty, contracting dims [1] of x_input and [1] of weight
    // weight shape: 7x7, input shape: 6x7
    // Result shape: 6x7
    %bmm_result = "stablehlo.dot_general"(%x_input, %bmm_weight) {
      dot_dimension_numbers = #stablehlo.dot<lhs_batching_dimensions = [], rhs_batching_dimensions = [], lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>
    } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

    // Step 2: Add bias to bmm_result
    // broadcast bias to shape 6x7
    %bias_broadcast = "stablehlo.broadcast_in_dim"(%bmm_bias) {
      broadcast_dimensions = array<i64: 0>
    } : (tensor<7xf32>) -> tensor<6x7xf32>
    %bmm_bias_added = "stablehlo.add"(%bmm_result, %bias_broadcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

    // Step 3: Instance normalization
    // Reshape to 4D: (6,1,1,7) for normalization
    %shape_b = "stablehlo.reshape"(%bmm_bias_added) {
      T = tensor<6x7xf32>
    } : (tensor<6x7xf32>) -> tensor<6x7xf32>
    // Reshape to 4D: (6,1,1,7)
    %bmm_4d = "stablehlo.reshape"(%bmm_bias_added) {
      T = tensor<6x7xf32>
    } : (tensor<6x7xf32>) -> tensor<6x1x1x7xf32>
    // Transpose to (6,7,1,1) for normalization
    %perm = array<i64: 0, 1, 2, 3>
    // Actually, to match the expected shape, we keep as (6,1,1,7)
    // InstanceNorm2d expects shape (N,C,H,W), so shape (6,7,1,1) is better
    // So, transpose to (6,7,1,1)
    %bmm_transposed = "stablehlo.transpose"(%bmm_4d) {
      permutation = array<i64: 0, 1, 2, 3>
    } : (tensor<6x1x1x7xf32>) -> tensor<6x1x1x7xf32>
    // Actually, keep shape as (6,7,1,1)
    // For normalization, shape (N,C,H,W) = (6,7,1,1)
    // So, reshape to (6,7,1,1)
    // But the current shape is (6,1,1,7), so transpose axes 1 and 3
    %perm_norm = array<i64: 0, 3, 1, 2>
    %bmm_norm_input = "stablehlo.transpose"(%bmm_4d) {
      permutation = %perm_norm
    } : (tensor<6x1x1x7xf32>) -> tensor<6x7x1x1>
    // Compute mean over H,W (axes 2,3)
    // reduce over axes 2 and 3
    %mean = "stablehlo.reduce"(%bmm_norm_input, %const_zero) {
      dimensions = array<i64: 2, 3>
    } : (tensor<6x7x1x1xf32>, tensor<f32>) -> tensor<6x7xf32>
    // Compute variance: (x - mean)^2, then reduce
    %bmm_centered = "stablehlo.subtract"(%bmm_norm_input, "stablehlo.broadcast_in_dim"(%mean) {
      broadcast_dimensions = array<i64: 1>
    }) : (tensor<6x7x1x1xf32>, tensor<6x7xf32>) -> tensor<6x7x1x1xf32>
    %bmm_centered_sq = "stablehlo.multiply"(%bmm_centered, %bmm_centered) : (tensor<6x7x1x1xf32>, tensor<6x7x1x1xf32>) -> tensor<6x7x1x1xf32>
    %var = "stablehlo.reduce"(%bmm_centered_sq, %const_zero) {
      dimensions = array<i64: 2, 3>
    } : (tensor<6x7x1x1xf32>, tensor<f32>) -> tensor<6x7xf32>
    // Compute std = sqrt(var + epsilon)
    %var_plus_eps = "stablehlo.add"(%var, "stablehlo.broadcast_in_dim"(%eps) {
      broadcast_dimensions = array<i64: 1>
    }) : (tensor<6x7xf32>, tensor<1xf32>) -> tensor<6x7xf32>
    %std = "stablehlo.sqrt"(%var_plus_eps) : tensor<6x7xf32>
    // Normalize: (x - mean) / std
    %bmm_norm = "stablehlo.divide"(
      "stablehlo.subtract"(%bmm_norm_input, "stablehlo.broadcast_in_dim"(%mean) {
        broadcast_dimensions = array<i64: 1>
      }),
      "stablehlo.broadcast_in_dim"(%std) {
        broadcast_dimensions = array<i64: 1>
      }
    ) : (tensor<6x7x1x1xf32>, tensor<6x7xf32>) -> tensor<6x7x1x1xf32>
    // Transpose back to (6,1,1,7)
    %bmm_norm_transposed = "stablehlo.transpose"(%bmm_norm) {
      permutation = array<i64: 0, 2, 3, 1>
    } : (tensor<6x7x1x1xf32>) -> tensor<6x1x1x7xf32>
    // Reshape back to (6,7)
    %bmm_norm_reshaped = "stablehlo.reshape"(%bmm_norm_transposed) {
      T = tensor<6x7xf32>
    } : (tensor<6x1x1x7xf32>) -> tensor<6x7xf32>

    // Step 4: Residual addition with y_input
    %residual = "stablehlo.add"(%bmm_norm_reshaped, %y_input) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

    // Step 5: Element-wise multiply with y_input
    %output = "stablehlo.multiply"(%residual, %y_input) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

    // Return the result
    return %output : tensor<6x7xf32>
  }
