module {
  func.func @main(%arg0: tensor<1x1x1x1xf32>, %arg1: tensor<3x16x3x3x3xf32>, %arg2: tensor<16xf32>, %arg3: tensor<6x3x16x7x7xf32>) -> tensor<6x1x31x13x13xf32> {
    // Step 1: Transposed convolution
    %conv = "stablehlo.convolution"(%arg3, %arg1) {
      window_strides = dense<2>,
      padding = dense<[[1, 1], [1, 1], [1, 1]]>,
      lhs_dilation = dense<1, 1, 1, 1, 1>,
      rhs_dilation = dense<1, 1, 1, 1, 1>,
      feature_group_count = 1
    } : (tensor<6x3x16x7x7xf32>, tensor<3x16x3x3x3xf32>) -> tensor<6x16x31x13x13xf32>

    // Step 2: Reduce logsumexp over dimension 1 (channel dimension)
    // First, compute max for numerical stability
    %max_reduce = "stablehlo.reduce"(%conv) {
      dimensions = dense<1>,
      body = {
        ^bb0(%acc: tensor<6x1x31x13x13xf32>, %x: tensor<6x16x31x13x13xf32>) {
          %cmp = "stablehlo.compare"(%x, %acc) { comparison = "greater" } : (tensor<6x16x31x13x13xf32>, tensor<6x1x31x13x13xf32>) -> tensor<6x16x31x13x13xf32>
          %max = "stablehlo.select"(%cmp, %x, %acc) : (tensor<6x16x31x13x13xf32>, tensor<6x1x31x13x13xf32>) -> tensor<6x16x31x13x13xf32>
          return ^bb0(%max, %x)
        }
      }
    } : (tensor<6x16x31x13x13xf32>) -> tensor<6x16x31x13x13xf32>

    // Sum of exp(x - max) over channel dimension
    %sub_max = "stablehlo.subtract"(%conv, "stablehlo.broadcast_in_dim"(%max_reduce, dense<[1, 2, 3, 4]>, dense<0, 1, 2, 3>>)) : (tensor<6x16x31x13x13xf32>, tensor<6x1x31x13x13xf32>) -> tensor<6x16x31x13x13xf32>
    %exp_x = "stablehlo.exponential"(%sub_max) : (tensor<6x16x31x13x13xf32>) -> tensor<6x16x31x13x13xf32>
    %sum_exp = "stablehlo.reduce"(%exp_x) {
      dimensions = dense<1>,
      body = {
        ^bb0(%acc: tensor<6x1x31x13x13xf32>, %x: tensor<6x16x31x13x13xf32>) {
          %sum = "stablehlo.add"(%acc, %x) : (tensor<6x1x31x13x13xf32>, tensor<6x16x31x13x13xf32>) -> tensor<6x1x31x13x13xf32>
          return ^bb0(%sum, %x)
        }
      }
    } : (tensor<6x16x31x13x13xf32>) -> tensor<6x1x31x13x13xf32>

    // Compute logsumexp: max + log(sum_exp)
    %log_sum_exp = "stablehlo.log"("stablehlo.reduce"(%sum_exp) {
      dimensions = dense<1>,
      body = {
        ^bb0(%acc: tensor<6x1x31x13x13xf32>, %x: tensor<6x16x31x13x13xf32>) {
          %sum = "stablehlo.add"(%acc, %x) : (tensor<6x1x31x13x13xf32>, tensor<6x16x31x13x13xf32>) -> tensor<6x1x31x13x13xf32>
          return ^bb0(%sum, %x)
