  func.func @main(%arg0: tensor<6x7x8x8xf32>) -> tensor<6x7x8x8xf32> {
    // Step 1: Compute the Frobenius norm of the input tensor
    // torch.norm with p='fro' computes the Frobenius norm, which is equivalent to the L2 norm over all elements
    // in the tensor. In StableHLO, we can use reduce with multiply and sqrt to compute the Frobenius norm.

    // 1a. Compute sum of squares of all elements
    %zero = "stablehlo.constant"() {value = dense<0.0 : f32>} : () -> f32
    %sum_squares = "stablehlo.reduce"(%arg0, %zero)
      ({
