          %mul = "stablehlo.multiply"(%a, %a) : (tensor<f32>, tensor<f32>) -> tensor<f32>
          %add = "stablehlo.add"(%b, %mul) : (tensor<f32>, tensor<f32>) -> tensor<f32>
          "stablehlo.return"(%add) : (tensor<f32>) -> ()
      })
      {dimensions = array<i64: 0, 1, 2, 3>} : (tensor<6x7x8x8xf32>, tensor<f32>) -> tensor<f32>

    // 1b. Compute the Frobenius norm as sqrt of sum of squares
    %norm = "stablehlo.sqrt"(%sum_squares) : (tensor<f32>) -> tensor<f32>

