    %broadcast_dims = array<i64: 0, 1, 2, 3>
    %norm_broadcasted = "stablehlo.broadcast_in_dim"(%norm) {broadcast_dimensions = %broadcast_dims} : (tensor<f32>) -> tensor<6x7x8x8xf32>

    // Step 3: Divide input tensor by the norm
    %output = "stablehlo.divide"(%arg0, %norm_broadcasted) : (tensor<6x7x8x8xf32>, tensor<6x7x8x8xf32>) -> tensor<6x7x8x8xf32>

