  %one = "stablehlo.constant"() {value = dense<1> : tensor<i64>} : () -> tensor<i64>
  %kernel_minus_one = "stablehlo.subtract" %kernel_size, %one : tensor<i64>
  %pad_before = "stablehlo.divide" %kernel_minus_one, %one : tensor<i64> // integer division
  // For symmetric padding, pad_after same as pad_before
  %pad_after_h = "stablehlo.subtract" %pad_before, %one : tensor<i64>
  %pad_after_w = "stablehlo.subtract" %pad_before, %one : tensor<i64>

  // Create padding array: shape [input_rank, 2]
  // For input shape [batch, channels, height, width], pad height and width
  %padding_h = "stablehlo.concatenate"(%padding_value, %padding_value) : (tensor<i64>, tensor<i64>) -> tensor<2xi64>
  %padding_h = "stablehlo.concatenate"(%pad_before, %pad_after_h) : (tensor<i64>, tensor<i64>) -> tensor<2xi64>
  %padding_w = "stablehlo.concatenate"(%padding_value, %padding_value) : (tensor<i64>, tensor<i64>) -> tensor<2xi64>
  %padding_w = "stablehlo.concatenate"(%pad_before, %pad_after_w) : (tensor<i64>, tensor<i64>) -> tensor<2xi64>
  // Stack to form padding tensor of shape [4, 2]
  %padding_h_w = "stablehlo.concatenate"(%padding_h, %padding_w) : (tensor<2xi64>, tensor<2xi64>) -> tensor<4x2xi64>

  // Pad the input tensor
  %padded_input = "stablehlo.pad"(%arg0) {padding = %padding_h_w} : (tensor<16x16x16x16xf32>) -> tensor<18x18x16x16xf32>

  // Compute output shape for height and width: floor((input_dim + pad_before + pad_after - kernel_size) / stride) + 1
  // input height and width are 16
  %input_dim_h = "stablehlo.constant"() {value = dense<16> : tensor<i64>} : () -> tensor<i64>
  %input_dim_w = "stablehlo.constant"() {value = dense<16> : tensor<i64>} : () -> tensor<i64>

  // Compute numerator for height and width
  %numerator_h = "stablehlo.subtract" %input_dim_h, %kernel_size : tensor<i64>
  %numerator_w = "stablehlo.subtract" %input_dim_w, %kernel_size : tensor<i64>

  // Add padding
  %padded_h = "stablehlo.add" %input_dim_h, %pad_before : tensor<i64>
  %padded_h2 = "stablehlo.add" %padded_h, %pad_after_h : tensor<i64>
  %padded_w = "stablehlo.add" %input_dim_w, %pad_before : tensor<i64>
  %padded_w2 = "stablehlo.add" %padded_w, %pad_after_w : tensor<i64>

  // Compute output height and width
  // out_dim = floor((padded_dim - kernel_size) / stride) + 1
  %numerator_h2 = "stablehlo.subtract" %padded_h2, %kernel_size : tensor<i64>
  %out_h_float = "stablehlo.divide" %numerator_h2, %stride : tensor<i64>
  // floor is implicit in integer division
  %out_h = "stablehlo.floor" %out_h_float : tensor<i64>
  %out_h_plus_one = "stablehlo.add" %out_h, %one : tensor<i64>

  %numerator_w2 = "stablehlo.subtract" %padded_w2, %kernel_size : tensor<i64>
  %out_w_float = "stablehlo.divide" %numerator_w2, %stride : tensor<i64>
  %out_w = "stablehlo.floor" %out_w_float : tensor<i64>
