  %window_dims = "stablehlo.concatenate"(%kernel_size, %kernel_size) : (tensor<i64>, tensor<i64>) -> tensor<2xi64>
  %window_dims_full = "stablehlo.concatenate"(%one, %one) : (tensor<i64>, tensor<i64>) -> tensor<2xi64>
