  %window_dims_final = "stablehlo.concatenate"(%one, %window_dims_4d) : (tensor<i64>, tensor<4xi64>) -> tensor<4xi64>

  // Define strides: [1, 1, stride, stride]
  %strides = "stablehlo.concatenate"(%one, %stride) : (tensor<i64>, tensor<i64>) -> tensor<2xi64>
  %strides_full = "stablehlo.concatenate"(%one, %strides) : (tensor<i64>, tensor<2xi64>) -> tensor<4xi64>
  // For 4D strides
  %strides_4d = "stablehlo.concatenate"(%one, %strides_full) : (tensor<i64>, tensor<4xi64>) -> tensor<4xi64>

  // Padding for reduce_window: no padding (all zeros)
  %padding_reduce = "stablehlo.constant"() {value = dense<0> : tensor<i64>} : () -> tensor<2xi64>
  %padding_array = "stablehlo.concatenate"(%padding_reduce, %padding_reduce) : (tensor<i64>, tensor<i64>) -> tensor<2xi64>
  %padding_full = "stablehlo.concatenate"(%padding_array, %padding_array) : (tensor<2xi64>, tensor<2xi64>) -> tensor<4x2xi64>

