  // Number of elements = kernel_size * kernel_size
  %kernel_size_f32 = "stablehlo.convert" %kernel_size : (tensor<i64>) -> tensor<f32>
  %num_elements = "stablehlo.multiply" %kernel_size_f32, %kernel_size_f32 : tensor<f32>
