  %gemm_out = "stablehlo.dot_general"(%arg1, %arg0) {dot_dimension_numbers = %dot_dim_nums} : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Step 2: BatchNorm (GroupNorm in training mode): compute mean and variance over batch
  // For simplicity, assume mean and variance are computed over batch dimension (0)
  // Compute mean: reduce over dimension 0
  %reduce_dims = array<i64: 0>
  %mean = "stablehlo.reduce"(%gemm_out, %const_zero) {
    dimensions = %reduce_dims
  } : (tensor<16x16xf32>, tensor<f32>) -> tensor<16x16xf32>
  // Initialize zero tensor for reduction
  %const_zero = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
  // Compute squared difference: (x - mean)^2
  %diff = "stablehlo.subtract"(%gemm_out, %mean) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
  %diff_sq = "stablehlo.multiply"(%diff, %diff) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
  // Compute variance: reduce over batch
  %var = "stablehlo.reduce"(%diff_sq, %const_zero) {
    dimensions = %reduce_dims
  } : (tensor<16x16xf32>, tensor<f32>) -> tensor<16x16xf32>
  // Compute batch norm: (x - mean) / sqrt(variance + epsilon)
  %epsilon = "stablehlo.constant"() {value = dense<1e-5> : tensor<f32>} : () -> tensor<f32>
  %var_plus_eps = "stablehlo.add"(%var, %epsilon) : (tensor<16x16xf32>, tensor<f32>) -> tensor<16x16xf32>
  %inv_std = "stablehlo.rsqrt"(%var_plus_eps) : (tensor<16x16xf32>) -> tensor<16x16xf32>
  // Normalize: (x - mean) * inv_std
  %x_minus_mean = "stablehlo.subtract"(%gemm_out, %mean) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
  %normalized = "stablehlo.multiply"(%x_minus_mean, %inv_std) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

