  // So define constant one
  %const_one = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
  %neg_x = "stablehlo.negate"(%normalized) : (tensor<16x16xf32>) -> tensor<16x16xf32>
  %exp_neg_x = "stablehlo.exponential"(%neg_x) : (tensor<16x16xf32>) -> tensor<16x16xf32>
  %denominator = "stablehlo.add"(%const_one, %exp_neg_x) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
  %sigmoid = "stablehlo.divide"(%const_one, %denominator) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
  // Swish: x * sigmoid(x)
  %swish1 = "stablehlo.multiply"(%normalized, %sigmoid) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

