  // %arg3: group_norm.weight (tensor<16xf32>)
  // Broadcast to shape [16,16]
  %broadcast_weight = "stablehlo.broadcast_in_dim"(%arg3) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %mul1 = "stablehlo.multiply"(%swish1, %broadcast_weight) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

