  // Reuse sigmoid(x) computed earlier
  %swish2 = "stablehlo.multiply"(%mul1, %sigmoid) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Final output
  return %swish2 : tensor<16x16xf32>
