    %rows = "stablehlo.iota"() {iota_dimension = 0 : i64, iota_shape = dense<5> : tensor<i64>} : () -> tensor<5xi64>
    // Generate column indices (iota along dimension 1)
    %cols = "stablehlo.iota"() {iota_dimension = 1 : i64, iota_shape = dense<5> : tensor<i64>} : () -> tensor<5xi64>
