    %scaled_norm = "stablehlo.multiply"(%normalized, %gn_weight_bcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
    %shifted_norm = "stablehlo.add"(%scaled_norm, %gn_bias_bcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

