    // Swish: x * sigmoid(x)
    %swish1 = "stablehlo.multiply"(%shifted_norm, %sigmoid_bcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

    // Step 7: Multiply by multiply_weight (arg0)
    %multiply_weight_bcast = "stablehlo.broadcast_in_dim"(%arg0) {broadcast_dimensions = array<i64: 0>} : (tensor<16xf32>) -> tensor<16x16xf32>
    %x_times_weight = "stablehlo.multiply"(%swish1, %multiply_weight_bcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

