    %denominator2 = "stablehlo.add"(%one, %exp_neg_x2) : (tensor<f32>, tensor<f32>) -> tensor<f32>
    %sigmoid_x2 = "stablehlo.divide"(%one, %denominator2) : (tensor<f32>, tensor<f32>) -> tensor<f32>
    %sigmoid_bcast2 = "stablehlo.broadcast_in_dim"(%sigmoid_x2) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<f32>) -> tensor<16x16xf32>
    %swish2 = "stablehlo.multiply"(%x_times_weight, %sigmoid_bcast2) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

