    // Step 1: Compute linear(x) = matmul(%arg2, %arg0^T) + %arg1
    // Transpose %arg0 to get shape (7x7) -> (7x7) (identity, but explicit for clarity)
    %arg0_T = "stablehlo.transpose"(%arg0) {permutation = [1, 0]} : (tensor<7x7xf32>) -> tensor<7x7xf32>
    // Dot general: %matmul = %arg2 (6x7) x %arg0_T (7x7) -> (6x7)
    %dot_result = "stablehlo.dot_general"(%arg2, %arg0_T) {
      dot_dimension_numbers = #stablehlo.dot<lhs_batching_dimensions = [], rhs_batching_dimensions = [], lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>
    } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
    // Add bias: %linear = %dot_result + %arg1 (broadcasted)
    // Broadcast %arg1 to shape (6x7)
    %bias_bcast = "stablehlo.broadcast_in_dim"(%arg1) {
      broadcast_dimensions = [0]
    } : (tensor<7xf32>) -> tensor<6x7xf32>
    %linear = "stablehlo.add"(%dot_result, %bias_bcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
    // Step 2: Apply sigmoid: sigmoid(x) = 1 / (1 + exp(-x))
    // Compute -x
    %neg_linear = "stablehlo.negate"(%linear) : (tensor<6x7xf32>) -> tensor<6x7xf32>
    // exp(-x)
    %exp_neg = "stablehlo.exponential"(%neg_linear) : (tensor<6x7xf32>) -> tensor<6x7xf32>
    // 1.0 constant
    %one_const = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
    // 1 + exp(-x)
    %denominator = "stablehlo.add"(%one_const, %exp_neg) : (tensor<f32>, tensor<f32>) -> tensor<f32>
    // reciprocal: 1 / (1 + exp(-x))
    %sigmoid = "stablehlo.divide"(%one_const, %denominator) : (tensor<f32>, tensor<f32>) -> tensor<f32>
    // Broadcast sigmoid to shape (6x7)
    %sigmoid_bcast = "stablehlo.broadcast_in_dim"(%sigmoid) {
      broadcast_dimensions = [0, 1]
    } : (tensor<6x7xf32>) -> tensor<6x7xf32>
    // Element-wise multiply: sigmoid(x) * x
    %mul_sigmoid_x = "stablehlo.multiply"(%sigmoid_bcast, %linear) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
    // Step 3: Sum over dim=1 (columns), keepdim=True -> shape (6x1)
    // Reduce sum over dimension 1
