       window_strides = %strides,
       padding = %padding,
       lhs_dilation = %lhs_dilation,
       rhs_dilation = %rhs_dilation,
       feature_group_count = %feature_group_count,
       batch_group_count = %batch_group_count} : tensor<6x16x13x4x4xf32>

    // Step 2: HardSwish activation
    // x * relu6(x + 3) / 6
    %zero = "stablehlo.constant"() {value = 0.0 : f32} : () -> f32
    %one = "stablehlo.constant"() {value = 1.0 : f32} : () -> f32
    %three = "stablehlo.constant"() {value = 3.0 : f32} : () -> f32
    %six = "stablehlo.constant"() {value = 6.0 : f32} : () -> f32

    // x + 3
    %x_plus_3 = "stablehlo.add"(%conv_result, %three) : tensor<6x16x13x4x4xf32>
    // relu6(x+3) = min(max(x+3, 0), 6)
    %relu6_part1 = "stablehlo.maximum"(%x_plus_3, %zero) : tensor<6x16x13x4x4xf32>
    %relu6 = "stablehlo.minimum"(%relu6_part1, %six) : tensor<6x16x13x4x4xf32>
    // x * relu6(x+3) / 6
    %mul = "stablehlo.multiply"(%conv_result, %relu6) : tensor<6x16x13x4x4xf32>
    %hardswish = "stablehlo.divide"(%mul, %six) : tensor<6x16x13x4x4xf32>

    // Step 3: GroupNorm
    // Reshape to (6,4,4,13,4,4)
    %shape = "stablehlo.shape"(%hardswish) : () -> tensor<5xi64>
    // For shape: (6,16,13,4,4)
