    %reshaped = "stablehlo.reshape"(%hardswish, %reshaped_shape) : tensor<6x4x4x13x4x4xf32>

    // Compute mean over axes [1,2]
    %axes = "stablehlo.constant"() {value = dense<[1,2]>} : () -> tensor<2xi64>
    // Sum over axes
    %sum = "stablehlo.reduce"(%reshaped, %zero, "stablehlo.add") {axes = %axes} : tensor<6x4x4x13x4x4xf32>
    // Number of elements in axes [1,2]: 4*4=16
    %num_elements = "stablehlo.constant"() {value = 16 : i64} : () -> i64
    // Convert to f32
    %num_elements_f32 = "stablehlo.convert"(%num_elements) : tensor<1xi64> to tensor<1xf32>
    // Broadcast to shape for division
    %num_elements_bcast = "stablehlo.broadcast_in_dim"(%num_elements_f32, %sum.shape, dense<[0]> : tensor<1xi64>) : tensor<6x4x4x13x4x4xf32>
    // Compute mean
    %mean = "stablehlo.divide"(%sum, %num_elements_bcast) : tensor<6x4x4x13x4x4xf32>

    // Broadcast mean back to shape for subtraction
    %mean_bcast = "stablehlo.broadcast_in_dim"(%mean, %reshaped_shape, dense<[0,1,2,3,4,5]> : tensor<6x6xi64>) : tensor<6x4x4x13x4x4xf32>

    // Subtract mean
    %x_minus_mean = "stablehlo.subtract"(%reshaped, %mean_bcast) : tensor<6x4x4x13x4x4xf32>

    // Square
    %x_minus_mean_sq = "stablehlo.multiply"(%x_minus_mean, %x_minus_mean) : tensor<6x4x4x13x4x4xf32>

    // Sum of squares over axes [1,2]
    %sum_sq = "stablehlo.reduce"(%x_minus_mean_sq, %zero, "stablehlo.add") {axes = %axes} : tensor<6x4x4x13x4x4xf32>
    // Variance = sum / 16
    %variance = "stablehlo.divide"(%sum_sq, %num_elements_bcast) : tensor<6x4x4x13x4x4xf32>
    // Add epsilon
    %epsilon = "stablehlo.constant"() {value = 1e-5 : f32} : () -> f32
    %variance_eps = "stablehlo.add"(%variance, %epsilon) : tensor<6x4x4x13x4x4xf32>
    // sqrt(variance + epsilon)
    %inv_std = "stablehlo.sqrt"(%variance_eps) : tensor<6x4x4x13x4x4xf32>
    // reciprocal
    %one_f32 = "stablehlo.constant"() {value = 1.0 : f32} : () -> f32
    %inv_std_recip = "stablehlo.divide"(%one_f32, %inv_std) : tensor<6x4x4x13x4x4xf32>

    // Normalize
    %x_norm = "stablehlo.multiply"(%x_minus_mean, %inv_std_recip) : tensor<6x4x4x13x4x4xf32>

