    %final_shape = "stablehlo.constant"() {value = dense<[6,16,13,4,4]>} : () -> tensor<5xi64>
    %x_norm_reshaped = "stablehlo.reshape"(%x_norm, %final_shape) : tensor<6x16x13x4x4xf32>

    // Return the normalized tensor
    return %x_norm_reshaped : tensor<6x16xf32>
  }
