    %three = "stablehlo.constant"() {value = dense<3.0> : tensor<f32>} : () -> tensor<f32>
    %six = "stablehlo.constant"() {value = dense<6.0> : tensor<f32>} : () -> tensor<f32>
    %three_broadcast = "stablehlo.broadcast_in_dim"(%three) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<f32>
    %six_broadcast = "stablehlo.broadcast_in_dim"(%six) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<f32>
    %x_plus_3 = "stablehlo.add"(%conv_biased, %three_broadcast) : (tensor<6x16x4x4x4xf32>, tensor<16x1x1x1x1xf32>) -> tensor<6x16x4x4x4xf32>
    // Clamp between 0 and 6
    %zero = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
    %zero_broadcast = "stablehlo.broadcast_in_dim"(%zero) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<f32>
