    %relu6 = "stablehlo.minimum"(%relu6_part1, %six_broadcast2) : (tensor<6x16x4x4x4xf32>, tensor<f32>) -> tensor<6x16x4x4x4xf32>
    // relu6(x) = min(max(x,0),6)
    // Compute relu6(x)
