    // Broadcast mean to shape of x1
    %mean_bcast = "stablehlo.broadcast_in_dim"(%mean) {
      broadcast_dimensions = array<i64: 0>
    } : (tensor<16x14x5x5xf32>) -> tensor<6x16x14x5x5xf32>
    // Compute difference
    %diff = "stablehlo.subtract"(%x1, %mean_bcast) : (tensor<6x16x14x5x5xf32>, tensor<6x16x14x5x5xf32>) -> tensor<6x16x14x5x5xf32>
    // Square difference
    %diff_sq = "stablehlo.multiply"(%diff, %diff) : (tensor<6x16x14x5x5xf32>, tensor<6x16x14x5x5xf32>) -> tensor<6x16x14x5x5xf32>
    // Compute variance
    %var = "stablehlo.reduce"(%diff_sq, %c0) {
