    %denominator = stablehlo.add %c_one, %exp_neg_x : tensor<16xf32>
    // sigmoid(x) = 1 / (1 + exp(-x))
    %sigmoid_x = stablehlo.divide %c_one, %denominator : tensor<16xf32>
    // matmul: %arg1 (16x16) * %arg5 (16x16) -> result (16x16)
    %matmul_result = stablehlo.dot_general %arg1, %arg5
      {dot_dimension_numbers = #stablehlo.dot<lhs_batching_dimensions = [], rhs_batching_dimensions = [], lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>}
      : tensor<16x16xf32>, tensor<16x16xf32> -> tensor<16x16xf32>
    // Swish activation: sigmoid(x) * x
    %swish = stablehlo.multiply %sigmoid_x, %matmul_result : tensor<16x16xf32>
    // Add bias: %arg2 (bias vector of shape 16) broadcasted to (16x16)
    %bias_broadcast = stablehlo.broadcast_in_dim %arg2
      {broadcast_dimensions = [1]} : tensor<16xf32> -> tensor<16x16xf32>
    %add_bias = stablehlo.add %swish, %bias_broadcast : tensor<16x16xf32>
