    %mean = "stablehlo.reduce"(%add_bias, %c_zero, "stablehlo.reduce_sum", %reduce_axes)
      {dimensions = [1], keep_dims = true} : tensor<16x16xf32>, tensor<f32> -> tensor<16x16xf32>
    // Compute variance: mean of squared differences
    %diff = stablehlo.subtract %add_bias, %mean : tensor<16x16xf32>
    %diff_squared = stablehlo.multiply %diff, %diff : tensor<16x16xf32>
    %var_sum = "stablehlo.reduce"(%diff_squared, %c_zero, "stablehlo.reduce_sum", %reduce_axes)
      {dimensions = [1], keep_dims = true} : tensor<16x16xf32>, tensor<f32> -> tensor<16x16xf32>
    // Variance = sum / features
    %features = constant dense<16.0> : tensor<f32>
    %variance = stablehlo.divide %var_sum, %features : tensor<16x16xf32>
    // Compute stddev = sqrt(variance + epsilon)
