    %stddev = stablehlo.sqrt %var_plus_epsilon : tensor<16x16xf32>
    // Normalize: (x - mean) / stddev
    %x_minus_mean = stablehlo.subtract %add_bias, %mean : tensor<16x16xf32>
    %normalized = stablehlo.divide %x_minus_mean, %stddev : tensor<16x16xf32>
