    %add_bias = stablehlo.add %swish, %bias_broadcast : tensor<16x16xf32>
    // Layer normalization via GroupNorm
    // Compute mean over last dimension (features)
    %reduce_axes = constant dense<[1]> : tensor<1>
    %mean = "stablehlo.reduce"(%add_bias, %c_zero, "stablehlo.reduce_sum", %reduce_axes)
