      {broadcast_dimensions = [1]} : tensor<16xf32> -> tensor<16x16xf32>
    %scaled = stablehlo.multiply %normalized, %scale_broadcast : tensor<16x16xf32>
    %output = stablehlo.add %scaled, %bias_broadcast2 : tensor<16x16xf32>
    return %output : tensor<16x16xf32>
  }
