                  %arg3: tensor<16xf32>, %arg4: tensor<16xf32>, %arg5: tensor<16x16xf32>) -> tensor<16x16xf32> {
    // %arg0: bias (tensor<16xf32>)
    // %arg1: matmul weight (tensor<16x16xf32>)
    // %arg2: matmul bias (tensor<16xf32>)
    // %arg3: group norm weight (tensor<16xf32>)
    // %arg4: group norm bias (tensor<16xf32>)
    // %arg5: input tensor (tensor<16x16xf32>)

    // Step 1: matrix multiplication: x = input @ weight^T + bias
    // Note: matmul in StableHLO: dot_general with appropriate dimension numbers
    %dim_numbers = "{" 
                     "lhs_contracting_dims = [1],"
                     "rhs_contracting_dims = [1],"
                     "lhs_batch_dims = [],"
                     "rhs_batch_dims = []"
                   "}"
    %matmul_result = "tensor<16x16xf32>" = "stablehlo.dot_general"(%arg5, %arg1, %dim_numbers)

    // Add bias: broadcast bias to shape [16,16]
    %bias_bcast = "tensor<16x16xf32>" = "stablehlo.broadcast_in_dim"(%arg2, dense<[16,16]>, dense<[0,1]>)
    %add_bias = "tensor<16x16xf32>" = "stablehlo.add"(%matmul_result, %bias_bcast)

    // Step 2: Swish activation: sigmoid(x) * x
    // sigmoid(x) = 1 / (1 + exp(-x))
    %neg_x = "tensor<16x16xf32>" = "stablehlo.negate"(%add_bias)
    %exp_neg_x = "tensor<16x16xf32>" = "stablehlo.exp"(%neg_x)
    %one = "tensor<16x16xf32>" = "stablehlo.constant"() {value = dense<[1.0]> : tensor<1xf32>} : tensor<1xf32>
    %one_bcast = "tensor<16x16xf32>" = "stablehlo.broadcast_in_dim"(%one, dense<[16,16]>, dense<[0,1]>)
    %denominator = "tensor<16x16xf32>" = "stablehlo.add"(%one_bcast, %exp_neg_x)
    %sigmoid_x = "tensor<16x16xf32>" = "stablehlo.divide"(%one_bcast, %denominator)

    // Swish: sigmoid(x) * x
    %swish = "tensor<16x16xf32>" = "stablehlo.multiply"(%sigmoid_x, %add_bias)

