    // Broadcast bias to shape [16,16]
    %bias_bcast2 = "tensor<16x16xf32>" = "stablehlo.broadcast_in_dim"(%arg0, dense<[16,16]>, dense<[0,1]>)
    %swish_bias = "tensor<16x16xf32>" = "stablehlo.add"(%swish, %bias_bcast2)

    // Step 4: Apply GroupNorm
    // GroupNorm: normalize over features with scale and bias
    // For simplicity, assume mean and variance are computed over batch dimension (dim 0)
    // Compute mean over batch (dim 0)
    %zero = "tensor<1xf32>" = "stablehlo.constant"() {value = dense<[0.0]> : tensor<1xf32>}
    %reduction_dims = dense<[0]> // reduce over batch dimension
    %mean = "tensor<16x16xf32>" = "stablehlo.reduce"(%swish_bias, %zero, "add", %reduction_dims)
    // Divide by batch size (16)
    %batch_size = "tensor<1xf32>" = "stablehlo.constant"() {value = dense<[16.0]> : tensor<1xf32>}
    %mean_bcast = "tensor<16x16xf32>" = "stablehlo.broadcast_in_dim"(%mean, dense<[16,16]>, dense<[0,1]>)
    %mean_scaled = "tensor<16x16xf32>" = "stablehlo.divide"(%mean_bcast, %batch_size)

    // Compute variance: E[(x - mean)^2]
    %diff = "tensor<16x16xf32>" = "stablehlo.subtract"(%swish_bias, %mean_bcast)
    %diff_sq = "tensor<16x16xf32>" = "stablehlo.multiply"(%diff, %diff)
