    %epsilon = "tensor<1xf32>" = "stablehlo.constant"() {value = dense<[1e-5]> : tensor<1xf32>}
    %var_eps = "tensor<16x16xf32>" = "stablehlo.add"(%var, "stablehlo.broadcast_in_dim"(%epsilon, dense<[16,16]>, dense<[0,1]>))
    %stddev = "tensor<16x16xf32>" = "stablehlo.sqrt"(%var_eps)

