    %neg_x = "stablehlo.negate"(%matmul) : (tensor<16x16xf32>) -> tensor<16x16xf32>
    // exp(-x)
    %exp_neg_x = "stablehlo.exponential"(%neg_x) : (tensor<16x16xf32>) -> tensor<16x16xf32>
    // 1 + exp(-x)
    %one = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
    %denominator = "stablehlo.add"(%one, %exp_neg_x) : (tensor<f32>, tensor<f32>) -> tensor<f32>
    // reciprocal
    %recip = "stablehlo.rsqrt"(%denominator) : (tensor<f32>) -> tensor<f32>
    // But rsqrt is reciprocal of sqrt, so better to do 1 / denominator
    // Use convert to get 1.0 as tensor
    // Alternatively, use "stablehlo.divide" with numerator 1.0
    %one_tensor = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
    %sigmoid = "stablehlo.divide"(%one_tensor, %denominator) : (tensor<f32>, tensor<f32>) -> tensor<f32>

    // Step 3: multiply sigmoid(x) * x
    %swish = "stablehlo.multiply"(%sigmoid, %matmul) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

    // Step 4: add bias (%arg2) to swish
    // %arg2 is shape (16), need to broadcast to (16,16)
