    %bias_bcast2 = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = [0]} : (tensor<16xf32>) -> tensor<16x16xf32>
    // Actually, to match shape, broadcast bias to (16,16)
    // But broadcasting bias of shape (16) to (16,16) with broadcast_dimensions [0]
    // Alternatively, broadcast bias to shape (16,1), then broadcast again
    // For simplicity, broadcast bias to shape (16,16)
    %bias_bcast = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = [0]} : (tensor<16xf32>) -> tensor<16x16xf32>
    // Add bias
    %add_bias = "stablehlo.add"(%swish, %bias_bcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

    // Step 5: apply group normalization
    // group_norm.weight = %arg3 (shape (16))
    // group_norm.bias = %arg4 (shape (16))
    // group_norm expects input shape (batch, features)
    // For simplicity, assume batch size is 16, features=16
    // Broadcast weight and bias to shape (16,16)
    %gn_weight_bcast = "stablehlo.broadcast_in_dim"(%arg3) {broadcast_dimensions = [0]} : (tensor<16xf32>) -> tensor<16x16xf32>
    %gn_bias_bcast = "stablehlo.broadcast_in_dim"(%arg4) {broadcast_dimensions = [0]} : (tensor<16xf32>) -> tensor<16x16xf32>
    // Compute mean and variance for batch normalization
    // For simplicity, assume batch normalization in training mode:
    // mean = reduce_mean over batch dimension (dimension 0)
    // variance = reduce_variance over batch dimension
    // reduce_mean
    %axes0 = array<i64: 0>
    %mean = "stablehlo.reduce"(%add_bias, %zero) {dimensions = %axes0} : (tensor<16x16xf32>, tensor<f32>) -> tensor<16xf32>
    // For variance, compute (x - mean)^2, then reduce_mean
    // Expand mean to shape (16,16)
    %mean_bcast = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = [0]} : (tensor<16xf32>) -> tensor<16x16xf32>
    // x - mean
    %x_minus_mean = "stablehlo.subtract"(%add_bias, %mean_bcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
    // square
    %x_minus_mean_sq = "stablehlo.multiply"(%x_minus_mean, %x_minus_mean) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
    // variance
    %variance = "stablehlo.reduce"(%x_minus_mean_sq, %zero) {dimensions = %axes0} : (tensor<16x16xf32>, tensor<f32>) -> tensor<16xf32>
    // For normalization: (x - mean) / sqrt(variance + epsilon)
    %epsilon = "stablehlo.constant"() {value = dense<1e-5> : tensor<f32>} : () -> tensor<f32>
    %var_plus_eps = "stablehlo.add"(%variance, %epsilon) : (tensor<16xf32>, tensor<f32>) -> tensor<16xf32>
    %inv_std = "stablehlo.rsqrt"(%var_plus_eps) : (tensor<16xf32>) -> tensor<16xf32>
    // broadcast inv_std to shape (16,16)
    %inv_std_bcast = "stablehlo.broadcast_in_dim"(%inv_std) {broadcast_dimensions = [0]} : (tensor<16xf32>) -> tensor<16x16xf32>
    // normalize
    %x_centered = "stablehlo.subtract"(%add_bias, %mean_bcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
    %x_norm = "stablehlo.multiply"(%x_centered, %inv_std_bcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

    // Output tensor
    return %x_norm : tensor<16x16xf32>
  }
