func.func @main(%arg0: tensor<6xf32>, %arg1: tensor<6xf32>, %arg2: tensor<6x6x7x7xf32>) -> tensor<6x6x7x7xf32> {
  // Step 1: Compute mean over spatial dimensions (dims 2 and 3)
  %dims_spatial = constant dense<[2, 3]> : tensor<2xi64>
  %mean = "stablehlo.reduce"(%arg2, %c0 = "stablehlo.constant"() {value=dense<0.0> : tensor<f32>}) {dimensions = %dims_spatial} : (tensor<6x6x7x7xf32>, tensor<f32>) -> tensor<6x6x7x7xf32>
  // The reduction computes mean over dims 2 and 3, resulting in shape [6,6,1,1]
  // But since reduce reduces dims, shape of mean is [6,6,1,1]
  // To get shape [6,6], we need to reshape or broadcast accordingly
  // For simplicity, we can broadcast mean to shape [6,6,7,7]
  // Step 2: Compute variance over spatial dims
  // First, broadcast mean to shape [6,6,7,7]
  %mean_bcast = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = dense<[0,1,2,3]>} : (tensor<6x6x1x1xf32>) -> tensor<6x6x7x7xf32>
  // Step 3: Compute (x - mean_bcast)
  %x_minus_mean = "stablehlo.subtract" %arg2, %mean_bcast : tensor<6x6x7x7xf32>, tensor<6x6x7x7xf32>
  // Step 4: Square the difference
  %diff_sq = "stablehlo.multiply" %x_minus_mean, %x_minus_mean : tensor<6x6x7x7xf32>, tensor<6x6x7x7xf32>
  // Step 5: Compute variance as mean of squared differences over spatial dims
  %var = "stablehlo.reduce"(%diff_sq, %c0 = "stablehlo.constant"() {value=dense<0.0> : tensor<f32>}) {dimensions = %dims_spatial} : (tensor<6x6x7x7xf32>, tensor<f32>) -> tensor<6x6x7x7xf32>
  // Broadcast variance to shape [6,6,7,7]
  %var_bcast = "stablehlo.broadcast_in_dim"(%var) {broadcast_dimensions = dense<[0,1,2,3]>} : (tensor<6x6x1x1xf32>) -> tensor<6x6x7x7xf32>
  // Step 6: Compute std = sqrt(variance + epsilon)
  %epsilon = "stablehlo.constant"() {value=dense<1e-5 : f32>} : () -> tensor<f32>
  %var_plus_epsilon = "stablehlo.add" %var_bcast, %epsilon : tensor<6x6x7x7xf32>, tensor<f32>
  %std = "stablehlo.sqrt" %var_plus_epsilon : tensor<6x6x7x7xf32>
  // Step 7: Normalize input: (x - mean_bcast) / std
  %x_centered = "stablehlo.subtract" %arg2, %mean_bcast : tensor<6x6x7x7xf32>, tensor<6x6x7x7xf32>
  %x_norm = "stablehlo.divide" %x_centered, %std : tensor<6x6x7x7xf32>, tensor<6x6x7x7xf32>
  // Step 8: Reshape weight and bias for broadcasting
  // weight: shape [6], bias: shape [6]
  // Broadcast to shape [6,1,1,1]
  %weight_bcast = "stablehlo.broadcast_in_dim"(%arg0) {broadcast_dimensions = dense<[0]>} : (tensor<6xf32>) -> tensor<6x1x1x1xf32>
  %bias_bcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = dense<[0]>} : (tensor<6xf32>) -> tensor<6x1x1x1xf32>
  // Step 9: Apply affine transformation: y = weight * x_norm + bias
  %scaled = "stablehlo.multiply" %weight_bcast, %x_norm : tensor<6x1x1x1xf32>, tensor<6x6x7x7xf32>
  %y = "stablehlo.add" %scaled, %bias_bcast : tensor<6x6x7x7xf32>, tensor<6x1x1x1xf32>
  // Return the normalized, scaled, shifted tensor
  return %y : tensor<6x6x7x7xf32>
}
