module {
  func.func @main(%arg0: tensor<6xf32>, %arg1: tensor<6xf32>, %arg2: tensor<6x6x7x7xf32>) -> tensor<6x6x7x7xf32> {
    // %arg0: bn.weight (scale)
    // %arg1: bn.bias (bias)
    // %arg2: input tensor

    // Step 1: Compute mean over batch and spatial dims for each feature
    // Reduce over dims 0, 2, 3
    %dims = "tensor.dim"() {dim = 0} : () -> index
    %dims1 = "tensor.dim"() {dim = 2} : () -> index
    %dims2 = "tensor.dim"() {dim = 3} : () -> index

    // Create list of dims to reduce over
    %reduce_dims = "tensor.array"() : () -> tensor<3 x index>
    %reduce_dims = "tensor.insert"(%reduce_dims, %dims, 0) : (tensor<3 x index>, index, i64) -> tensor<3 x index>
    %reduce_dims = "tensor.insert"(%reduce_dims, %dims1, 1) : (tensor<3 x index>, index, i64) -> tensor<3 x index>
    %reduce_dims = "tensor.insert"(%reduce_dims, %dims2, 2) : (tensor<3 x index>, index, i64) -> tensor<3 x index>

    // Compute mean: sum over dims and divide by number of elements
    // Number of elements per feature: 6 * 7 * 7 = 294
    %num_elements = 294.0 : f32

    // Sum over dims 0,2,3
    %sum = "stablehlo.reduce"(%arg2) {reduction_kind = "add", dimensions = %reduce_dims} : (tensor<6x6x7x7xf32>) -> tensor<6x1x1x1xf32>

    // Broadcast sum to original shape for mean calculation
    %sum_bcast = "stablehlo.broadcast_in_dim"(%sum) {broadcast_dimensions = [0, 2, 3], shape = %arg2.shape} : (tensor<6x1x1x1xf32>) -> tensor<6x6x7x7xf32>

    // Compute mean
    %mean = "stablehlo.div"(%sum_bcast, %num_elements) : (tensor<6x6x7x7xf32>, f32) -> tensor<6x6x7x7xf32>

    // Step 2: Compute variance
    // diff = x - mean
    %diff = "stablehlo.sub"(%arg2, %mean) : (tensor<6x6x7x7xf32>, tensor<6x6x7x7xf32>) -> tensor<6x6x7x7xf32>

    // Square diff
    %diff_sq = "stablehlo.mul"(%diff, %diff) : (tensor<6x6x7x7xf32>, tensor<6x6x7x7xf32>) -> tensor<6x6x7x7xf32>

    // Sum squared diff over dims 0,2,3
    %sum_sq = "stablehlo.reduce"(%diff_sq) {reduction_kind = "add", dimensions = %reduce_dims} : (tensor<6x6x7x7xf32>) -> tensor<6x1x1x1xf32>

    // Compute variance
    %var = "stablehlo.div"(%sum_sq, %num_elements) : (tensor<6x1x1x1xf32>, f32) -> tensor<6x1x1x1xf32>

    // Broadcast variance to input shape
    %var_bcast = "stablehlo.broadcast_in_dim"(%var) {broadcast_dimensions = [0, 2, 3], shape = %arg2.shape} : (tensor<6x1x1x1xf32>) -> tensor<6x6x7x7xf32>

    // Step 3: Compute normalization
    // epsilon for numerical stability
    %epsilon = 1e-5 : f32

    // rsqrt of variance + epsilon
    %var_eps = "stablehlo.add"(%var_bcast, %epsilon) : (tensor<6x6x7x7xf32>, f32) -> tensor<6x6x7x7xf32>
    %rsqrt_var = "stablehlo.rsqrt"(%var_eps) : (tensor<6x6x7x7xf32>) -> tensor<6x6x7x7xf32>

    // normalized_x = (x - mean) * rsqrt_var
    %x_minus_mean = "stablehlo.sub"(%arg2, %mean) : (tensor<6x6x7x7xf32>, tensor<6x6x7x7xf32>) -> tensor<6x6x7x7xf32>
    %normalized = "stablehlo.mul"(%x_minus_mean, %rsqrt_var) : (tensor<6x6x7x7xf32>, tensor<6x6x7x7xf32>) -> tensor<6x6x7x7xf32>

    // Step 4: Scale and shift
    // %arg0: weight (scale), shape: [6]
    // %arg1: bias, shape: [6]

    // Broadcast weight and bias to shape of input
    // For broadcasting, specify broadcast_dimensions
    // shape of weight/bias: [6]
    // shape of normalized: [6,6,7,7]
    // broadcast_dimensions: [0,1,2,3]
    %bcast_weight = "stablehlo.broadcast_in_dim"(%arg0) {broadcast_dimensions = [0], shape = %arg2.shape} : (tensor<6xf32>) -> tensor<6x6x7x7xf32>
    %bcast_bias = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = [0], shape = %arg2.shape} : (tensor<6xf32>) -> tensor<6x6x7x7xf32>

    // Apply scale and shift
    %scaled = "stablehlo.mul"(%normalized, %bcast_weight) : (tensor<6x6x7x7xf32>, tensor<6x6x7x7xf32>) -> tensor<6x6x7x7xf32>
    %output = "stablehlo.add"(%scaled, %bcast_bias) : (tensor<6x6x7x7xf32>, tensor<6x6x7x7xf32>) -> tensor<6x6x7x7xf32>

    // Return the normalized output
    return %output : tensor<6x6x7x7xf32>
  }
}
