    // bias shape: [7], target shape: [6,7,4,4]
    // First, create a tensor of shape [6,7,4,4] filled with bias values broadcasted along batch and spatial dims
    // To do this, broadcast bias to shape [7], then reshape to [1,7,1,1], then broadcast to [6,7,4,4]
    // But since bias is 1D, we can broadcast directly
    // Create a tensor of shape [6,7,4,4] with bias broadcasted along batch and spatial dims
    // First, broadcast bias to shape [7], then reshape to [1,7,1,1], then broadcast to [6,7,4,4]
    %bias_broadcasted = "stablehlo.broadcast_in_dim"(%arg1) {
      broadcast_dimensions = array<i64: 1>
    } : (tensor<7xf32>) -> tensor<7xf32>
    // Reshape bias to [1,7,1,1]
    %bias_reshaped = "stablehlo.reshape"(%bias_broadcasted) {
      shape = array<i64: 1, 7, 1, 1>
    } : (tensor<7xf32>) -> tensor<1x7x1x1xf32>
    // Broadcast bias to shape [6,7,4,4]
    %bias_broadcasted_full = "stablehlo.broadcast_in_dim"(%bias_reshaped) {
      broadcast_dimensions = array<i64: 1, 2, 3>
    } : (tensor<1x7x1x1xf32>) -> tensor<6x7x4x4xf32>

    // Step 3: Add bias to convolution result
    %biased = "stablehlo.add"(%conv_result, %bias_broadcasted_full) : (tensor<7x7x4x4xf32>, tensor<6x7x4x4xf32>) -> tensor<6x7x4x4xf32>

