    %normalized = "stablehlo.divide"(%biased, %divisor_const) : (tensor<6x7x4x4xf32>, tensor<f32>) -> tensor<6x7x4x4xf32>

    // Step 5: Apply LeakyReLU with negative_slope=0.01
    // For LeakyReLU: if x >= 0 then x else 0.01 * x
    // Implemented as: select(x >= 0, x, 0.01 * x)
    // First, create constant 0.0
    %zero = "stablehlo.constant"() {value = dense<0x00000000> : tensor<f32>} : () -> tensor<f32>
