    // Step 3: HardSwish activation
    // HardSwish = x * relu6(x + 3) / 6
    %three = "constant"() {value = dense_float_attr<3.0>} : () -> f32
    %six = "constant"() {value = dense_float_attr<6.0>} : () -> f32
    %three_broadcast = "broadcast_in_dim"(%three) {broadcast_dimensions = []} : () -> tensor<> 
