// StableHLO program implementing the described model in MLIR dialect
module {
  func.func @main(%arg0: tensor<7x7xf32>,        // gemm.weight
                   %arg1: tensor<7xf32>,          // gemm.bias
                   %arg2: tensor<7xf32>,          // batch_norm.weight
                   %arg3: tensor<7xf32>,          // batch_norm.bias
                   %arg4: tensor<6x7xf32>) -> tensor<6x7xf32> { // input
    // Step 1: GEMM (Linear layer)
    // gemm: input (6x7), weight (7x7), bias (7)
    // Compute: matmul(input, weight^T) + bias
    %weight_t = "stablehlo.transpose"(%arg0) {permutation = [1, 0]} : (tensor<7x7xf32>) -> tensor<7x7xf32>
    %matmul = "stablehlo.dot_general"(%arg4, %weight_t) {
      dot_dimension_numbers = {
        lhs_contracting_dimensions = [1],
        rhs_contracting_dimensions = [0],
        lhs_batch_dimensions = [],
        rhs_batch_dimensions = []
      },
      precision_config = {use_default_precision = true}
    } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
    // Add bias: broadcast bias to shape (6,7)
    %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {
      broadcast_dimensions = [1],
      shape = tensor<6x7xf32>
    } : (tensor<7xf32>) -> tensor<6x7xf32>
    %gemm_output = "stablehlo.add"(%matmul, %bias_broadcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

    // Step 2: BatchNorm1d
    // batch_norm: input shape (6,7), weight (7), bias (7)
    // Compute mean and variance over batch (dim 0)
    %mean = "stablehlo.reduce"(%gemm_output, constant_f32_0) {
      dimensions = [0],
      reduction_kind = "mean"
    } : (tensor<6x7xf32>, tensor<0xf32>) -> tensor<7xf32>
    %mean_broadcast = "stablehlo.broadcast_in_dim"(%mean) {
      broadcast_dimensions = [0],
      shape = tensor<6x7xf32>
    } : (tensor<7xf32>) -> tensor<6x7xf32>
    // Compute variance
    %diff = "stablehlo.sub"(%gemm_output, %mean_broadcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
    %diff_squared = "stablehlo.mul"(%diff, %diff) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
    %var = "stablehlo.reduce"(%diff_squared, constant_f32_0) {
      dimensions = [0],
      reduction_kind = "mean"
    } : (tensor<6x7xf32>, tensor<0xf32>) -> tensor<7xf32>
    // Normalize: (x - mean) / sqrt(var + epsilon)
    %epsilon = constant_f32_1e-5
    %var_plus_epsilon = "stablehlo.add"(%var, %epsilon) : (tensor<7xf32>, tensor<7xf32>) -> tensor<7xf32>
    %inv_sqrt_var = "stablehlo.rsqrt"(%var_plus_epsilon) : (tensor<7xf32>) -> tensor<7xf32>
    // Broadcast mean and inv_sqrt_var to shape (6,7)
    %mean_bcast2 = "stablehlo.broadcast_in_dim"(%mean) {
      broadcast_dimensions = [0],
      shape = tensor<6x7xf32>
    } : (tensor<7xf32>) -> tensor<6x7xf32>
    %inv_sqrt_bcast = "stablehlo.broadcast_in_dim"(%inv_sqrt_var) {
      broadcast_dimensions = [0],
      shape = tensor<6x7xf32>
    } : (tensor<7xf32>) -> tensor<6x7xf32>
    // Normalize
