module {
  func.func @main(%arg0: tensor<7x7xf32>, %arg1: tensor<7xf32>, %arg2: tensor<7xf32>, %arg3: tensor<7xf32>, %arg4: tensor<6x7xf32>) -> tensor<6x7xf32> {
    // Step 1: GEMM (matrix multiplication)
    // %a = "stablehlo.dot_general"(%arg4, %arg0) with batch dims empty, contracting dims [1], [1]
    %a = "stablehlo.dot_general"(%arg4, %arg0) {
      dot_dimension_numbers = #stablehlo.dot<lhs_batching_dimensions = [], rhs_batching_dimensions = [], lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [1]>
    } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

    // Step 2: Add bias (%arg1) to GEMM result
    // Broadcast bias to shape [6,7]
    %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {
      broadcast_dimensions = array<i64: 0, 1>
    } : (tensor<7xf32>) -> tensor<6x7xf32>
    %add_bias = "stablehlo.add"(%a, %bias_broadcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

    // Step 3: BatchNorm
    // Broadcast batch norm weight and bias to shape [6,7]
    %bn_weight_broadcast = "stablehlo.broadcast_in_dim"(%arg2) {
      broadcast_dimensions = array<i64: 0>
    } : (tensor<7xf32>) -> tensor<6x7xf32>
    %bn_bias_broadcast = "stablehlo.broadcast_in_dim"(%arg3) {
      broadcast_dimensions = array<i64: 0>
    } : (tensor<7xf32>) -> tensor<6x7xf32>

    // Compute mean and variance over batch dimension (dim 0)
    // Reduce mean
    %mean = "stablehlo.reduce"(%add_bias, %zero_f32) {
      dimensions = array<i64: 0>
    } ({ ^bb0(%x: tensor<6x7xf32>, %b: tensor<f32>): tensor<f32> {
      %s = "stablehlo.add"(%x, %b) : (tensor<6x7xf32>, tensor<f32>) -> tensor<6x7xf32>
      "stablehlo.return"(%s) : (tensor<6x7xf32>) -> ()
    } }) : (tensor<6x7xf32>, tensor<f32>) -> tensor<6x7xf32>

    // But in StableHLO, reduce returns shape with reduced dims removed, so to get mean over batch:
    // We need to reduce over dimension 0, then broadcast back
    // For simplicity, compute mean over batch dimension:
    // First, reduce over dimension 0
    %sum = "stablehlo.reduce"(%add_bias, %zero_f32) {
      dimensions = array<i64: 0>
    } ({ ^bb0(%x: tensor<6x7xf32>, %b: tensor<f32>): tensor<f32> {
      %s = "stablehlo.add"(%x, %b) : (tensor<6x7xf32>, tensor<f32>) -> tensor<6x7xf32>
      "stablehlo.return"(%s) : (tensor<6x7xf32>) -> ()
    } }) : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>

    // Actually, better to reduce over dimension 0 to get shape [7], then broadcast
    // So, reduce over dimension 0
    %sum_over_batch = "stablehlo.reduce"(%add_bias, %zero_f32) {
      dimensions = array<i64: 0>
    } ({ ^bb0(%x: tensor<6x7xf32>, %b: tensor<f32>): tensor<f32> {
      %s = "stablehlo.add"(%x, %b) : (tensor<6x7xf32>, tensor<f32>) -> tensor<6x7xf32>
      "stablehlo.return"(%s) : (tensor<6x7xf32>) -> ()
    } }) : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>

    // Compute mean by dividing sum by batch size (6)
    %batch_size_f32 = "stablehlo.constant"() {value = dense<6.0> : tensor<f32>} : () -> tensor<f32>
    %mean_vals = "stablehlo.divide"(%sum_over_batch, %batch_size_f32) : (tensor<7xf32>, tensor<f32>) -> tensor<7xf32>

    // Broadcast mean to shape [6,7]
    %mean_broadcast = "stablehlo.broadcast_in_dim"(%mean_vals) {
      broadcast_dimensions = array<i64: 0>
    } : (tensor<7xf32>) -> tensor<6x7xf32>

    // Compute variance: sum of squared differences
    %diff = "stablehlo.subtract"(%add_bias, %mean_broadcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
    %diff_squared = "stablehlo.multiply"(%diff, %diff) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
    // Sum over batch
    %sum_diff_squared = "stablehlo.reduce"(%diff_squared, %zero_f32) {
      dimensions = array<i64: 0>
    } ({ ^bb0(%x: tensor<6x7xf32>, %b: tensor<f32>): tensor<f32> {
      %s = "stablehlo.add"(%x, %b) : (tensor<6x7xf32>, tensor<f32>) -> tensor<6x7xf32>
      "stablehlo.return"(%s) : (tensor<6x7xf32>) -> ()
    } }) : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>
    // Compute variance
    %variance = "stablehlo.divide"(%sum_diff_squared, %batch_size_f32) : (tensor<7xf32>, tensor<f32>) -> tensor<7xf32>
    // Broadcast variance
    %variance_broadcast = "stablehlo.broadcast_in_dim"(%variance) {
      broadcast_dimensions = array<i64: 0>
    } : (tensor<7xf32>) -> tensor<6x7xf32>

    // Normalize: (x - mean) / sqrt(variance + epsilon)
    %epsilon = "stablehlo.constant"() {value = dense<1.0e-5> : tensor<f32>} : () -> tensor<f32>
    %var_plus_epsilon = "stablehlo.add"(%variance_broadcast, %epsilon) : (tensor<6x7xf32>, tensor<f32>) -> tensor<6x7xf32>
    %sqrt_var = "stablehlo.sqrt"(%var_plus_epsilon) : (tensor<6x7xf32>) -> tensor<6x7xf32>
    %x_minus_mean = "stablehlo.subtract"(%add_bias, %mean_broadcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
    %normalized = "stablehlo.divide"(%x_minus_mean, %sqrt_var) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

    // Step 4: Apply GELU
