    %gemm_dim_nums = #stablehlo.dot<lhs_batching_dimensions = [], rhs_batching_dimensions = [], lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>
    %gemm_result = "stablehlo.dot_general"(%arg0, %arg0) {dot_dimension_numbers = %gemm_dim_nums} : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
    // Add bias
    // Broadcast bias to shape [6,7]
    %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
    %gemm_bias = "stablehlo.add" %gemm_result, %bias_broadcast : tensor<6x7xf32>

    // Step 2: BatchNorm
    // batch_norm parameters: weight (%arg2), bias (%arg3)
    // For simplicity, assume running mean=0 and running var=1 (not provided), so normalization reduces to scale and shift
    // Normalize: (x - mean) / sqrt(var + epsilon)
    // Here, mean=0, var=1, epsilon=1e-5
    // Compute: normalized_x = (x - 0) / sqrt(1 + 1e-5) = x / sqrt(1 + 1e-5)
    // scale: %arg2, bias: %arg3
    // For batch norm in training mode, normally compute batch mean and var, but here, for simplicity, assume fixed
    // So, normalized = gemm_bias * batch_norm_weight + batch_norm_bias
    // But in real, batch norm applies per feature: output = scale * normalized_x + bias
    // So, scale = %arg2, bias = %arg3
    // For simplicity, assume normalization is just scaling and shifting
    // First, scale
    %bn_scale = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = array<i64: 0>} : (tensor<7xf32>) -> tensor<6x7xf32>
    %bn_shift = "stablehlo.broadcast_in_dim"(%arg3) {broadcast_dimensions = array<i64: 0>} : (tensor<7xf32>) -> tensor<6x7xf32>
    // Apply scale
    %bn_scaled = "stablehlo.multiply" %gemm_bias, %bn_scale : tensor<6x7xf32>
