    %x_div_sqrt2 = "stablehlo.divide" %bn_output, %sqrt2 : tensor<6x7xf32>
    // erf(x / sqrt(2))
    %erf_x = "stablehlo.erf" %x_div_sqrt2 : tensor<6x7xf32> -> tensor<6x7xf32>
    // 1 + erf(...)
    %one = "stablehlo.constant"() {value = dense<1.0> } : () -> tensor<f32>
    %one_plus_erf = "stablehlo.add" %erf_x, %one : tensor<6x7xf32>
    // x * (1 + erf(...))
    %gelu_inner = "stablehlo.multiply" %bn_output, %one_plus_erf : tensor<6x7xf32>
    // 0.5 * x * (1 + erf(...))
    %half = "stablehlo.constant"() {value = dense<0.5> } : () -> tensor<f32>
    %gelu_output = "stablehlo.multiply" %gelu_inner, %half : tensor<6x7xf32>

    // Step 4: ReLU activation
    // ReLU: max(0, x)
    // constant 0
