// Complete StableHLO program implementing the described transposed 3D convolution
module {
  // Function signature: main(%arg0: tensor<6x6x3x3x3xf32>, %arg1: tensor<8x6x7x7x7xf32>) -> tensor<8x6x9x9x9xf32>
  func.func @main(%arg0: tensor<6x6x3x3x3xf32>, %arg1: tensor<8x6x7x7x7xf32>) -> tensor<8x6x9x9x9xf32> {
    // Aliases for input tensors
    %weight = %arg0 : tensor<6x6x3x3x3xf32>
    %input = %arg1 : tensor<8x6x7x7x7xf32>

    // Define constants for convolution parameters
    %in_channels = constant 6 : index
    %out_channels = constant 6 : index
    %kernel_size = constant 3 : index
    %stride = constant 1 : index
    %padding = constant 0 : index
    %output_padding = constant 0 : index

    // Compute output shape: (batch=8, channels=6, depth=9, height=9, width=9)
    // For transposed convolution, output shape calculation:
    // depth_out = (depth_in - 1) * stride - 2 * padding + kernel_size + output_padding
    // depth_in = 7
    // So, depth_out = (7 - 1)*1 - 0 + 3 + 0 = 6 + 3 = 9
    // Similarly for height and width
    %depth_in = 7 : index
    %height_in = 7 : index
    %width_in = 7 : index

    // Compute output spatial dimensions
    %depth_out = add(add(mul(%depth_in, %stride), -mul(%padding, 2)), add(%kernel_size, %output_padding))
    %height_out = add(add(mul(%height_in, %stride), -mul(%padding, 2)), add(%kernel_size, %output_padding))
    %width_out = add(add(mul(%width_in, %stride), -mul(%padding, 2)), add(%kernel_size, %output_padding))

    // Create shape for output tensor
    %output_shape = tensor<8x6x9x9x9> : tensor<5x:> // shape: [batch, channels, depth, height, width]
    %output_shape_tensor = tensor.from_elements(%depth_out, %out_channels, %depth_out, %height_out, %width_out) : tensor<5x:> 

    // Initialize output tensor with zeros
    %zero = constant 0.0 : f32
    %output = "stablehlo.constant"() {value = dense<0.0> : tensor<8x6x9x9x9>} : tensor<8x6x9x9x9>

    // Since StableHLO does not have a built-in conv_transpose, implement via reverse convolution
    // Approach:
    // 1. Reverse the weight tensor along spatial dimensions
    // 2. Perform a convolution with the input tensor using the reversed weight
    // 3. The convolution with reversed kernel acts as a transposed convolution

    // Reverse the kernel along spatial dimensions (dimensions 2,3,4)
    %reversed_weight = "stablehlo.reverse"(%weight) {dimensions = dense<[2,3,4]> : tensor<3>} : tensor<6x6x3x3x3>

    // Prepare for convolution:
    // Input shape: [8,6,7,7,7]
    // Kernel shape: [6,6,3,3,3]
    // Convolution parameters:
    //   window strides: [1,1,1]
    //   padding: [0,0,0]
