    %diff_sq = "stablehlo.multiply"(%diff, %diff) : (tensor<6x7x4x4xf32>, tensor<6x7x4x4xf32>) -> tensor<6x7x4x4xf32>
    // Reduce to get variance
    %var = "stablehlo.reduce"(%diff_sq, %dims_bn) {
      dimensions = %dims_bn,
      to_reduce = "stablehlo.mean"
