    %bn_bias_bcast = "stablehlo.broadcast_in_dim"(%bn_bias_reshaped) {
      shape = dense<6, 7, 4, 4>,
      broadcast_dimensions = dense<1, 2, 3>
    } : (tensor<1x7x1x1>) -> tensor<6x7x4x4xf32>

    // Scale and shift
    %scaled = "stablehlo.multiply"(%bn_output, %bn_weight_bcast) : (tensor<6x7x4x4xf32>, tensor<6x7x4x4xf32>) -> tensor<6x7x4x4xf32>
    %shifted = "stablehlo.add"(%scaled, %bn_bias_bcast) : (tensor<6x7x4x4xf32>, tensor<6x7x4x4xf32>) -> tensor<6x7x4x4xf32>

    // Step 4: Final scaling
    %scaling_factor = "stablehlo.constant"() {value = 2.0 : f32} : () -> f32
    %output = "stablehlo.multiply"(%shifted, %scaling_factor) : (tensor<6x7x4x4xf32>, f32) -> tensor<6x7x4x4xf32>

    // Return the result
    return %output : tensor<6x7x4x4xf32>
  }
