      dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1] -> [b, f, 0, 1]>,
      feature_group_count = 1 : i64,
      batch_group_count = 1 : i64
    } : (tensor<6x6x8x8xf32>, tensor<7x6x3x3xf32>) -> tensor<6x7x6x6xf32>

    // Step 3: Add bias
    // Broadcast bias to match convolution output shape
    // bias shape: [7]
    // convolution output shape: [6,7,6,6]
    // broadcast bias over batch, height, width
    %bias_bcast = "stablehlo.broadcast_in_dim"(%arg1) {
      broadcast_dimensions = array<i64: 1, 2, 3>
    } : (tensor<7xf32>) -> tensor<6x7x6x6xf32>

    %conv_bias = "stablehlo.add"(%conv, %bias_bcast) : (tensor<6x7x6x6xf32>, tensor<6x7x6x6xf32>) -> tensor<6x7x6x6xf32>

    // Step 4: Apply Mish activation: mish(x) = x * tanh(softplus(x))
    // Compute softplus(x) = log(1 + exp(x))
    %one = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
    %exp_x = "stablehlo.exponential"(%conv_bias) : (tensor<6x7x6x6xf32>) -> tensor<6x7x6x6xf32>
    %add_one = "stablehlo.add"(%exp_x, %one) : (tensor<6x7x6x6xf32>, tensor<1x7x6x6xf32>) -> tensor<6x7x6x6xf32>
    %softplus = "stablehlo.log"(%add_one) : (tensor<6x7x6x6xf32>) -> tensor<6x7x6x6xf32>

    // Compute tanh(softplus(x))
    %tanh_sp = "stablehlo.tanh"(%softplus) : (tensor<6x7x6x6xf32>) -> tensor<6x7x6x6xf32>

    // Compute Mish: x * tanh(softplus(x))
