    %exp_x2 = "stablehlo.exponential"(%mish) : (tensor<6x7x6x6xf32>) -> tensor<6x7x6x6xf32>
    %add_one2 = "stablehlo.add"(%exp_x2, %one) : (tensor<6x7x6x6xf32>, tensor<1x7x6x6xf32>) -> tensor<6x7x6x6xf32>
    %softplus2 = "stablehlo.log"(%add_one2) : (tensor<6x7x6x6xf32>) -> tensor<6x7x6x6xf32>
