    // and weight shape: [out_channels, in_channels, kernel_height, kernel_width]
    // Our weight shape: [7,6,3,3]
    %conv_result = "stablehlo.convolution"(%input_reshaped, %conv_weight)
      {window_strides = dense<[1,1]>, padding = dense<[0,0,0,0]>, lhs_dilation = dense<[1,1]>, rhs_dilation = dense<[1,1]>, feature_group_count = 1} : (tensor<6x6x8x8xf32>, tensor<7x6x3x3xf32>) -> tensor<6x7x6x6xf32>

    // Step 3: Add bias
