      dot_dimension_numbers = #stablehlo.dot<lhs_batching_dimensions = [], rhs_batching_dimensions = [], lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>
    } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

    // Step 2: broadcast bias to shape [7], then add to %matmul
    // Since bias shape is [7], broadcast to [6x7]
    %bias_bcast = "stablehlo.broadcast_in_dim"(%arg0) {
      broadcast_dimensions = array<i64: 0>
    } : (tensor<7xf32>) -> tensor<6x7xf32>

    // Add bias
    %add_bias = "stablehlo.add"(%matmul, %bias_bcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

    // Step 3: apply ReLU (which is max with zero)
    // Create constant zero tensor of shape [6x7]
    %zero_const = "stablehlo.constant"() {value = dense<0.0> : tensor<6x7xf32>} : () -> tensor<6x7xf32>

    // Compute max(%add_bias, 0)
    %relu = "stablehlo.maximum"(%add_bias, %zero_const) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

    // Return the result
