// StableHLO program implementing a forward pass of a HardSigmoid activation
// for input tensor of shape [6,7], matching the described Python model.

func.func @main(%arg0: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // Step 1: Define constants for 0.2 and 0.5
  %const_0_2 = "stablehlo.constant"() {value = dense<0.2> : tensor<f32>} : () -> tensor<f32>
  %const_0_5 = "stablehlo.constant"() {value = dense<0.5> : tensor<f32>} : () -> tensor<f32>
  // Constant 1.0 for clipping upper bound
  %const_1 = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
  // Constant 0.0 for clipping lower bound
  %const_0 = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>

  // Step 2: Compute x + 0.5
  %add_half = "stablehlo.add" %arg0, %const_0_5 : (tensor<6x7xf32>, tensor<f32>) -> tensor<6x7xf32>
  // Step 3: Compute x + 0.2
  %add_0_2 = "stablehlo.add" %arg0, %const_0_2 : (tensor<6x7xf32>, tensor<f32>) -> tensor<6x7xf32>

  // Step 4: Compute max(0, x + 0.2)
  %max_0 = "stablehlo.maximum" %add_0_2, %const_0 : (tensor<6x7xf32>, tensor<f32>) -> tensor<6x7xf32>
  // Step 5: Compute min(1, x + 0.5)
  %min_1 = "stablehlo.minimum" %add_half, %const_1 : (tensor<6x7xf32>, tensor<f32>) -> tensor<6x7xf32>

  // Step 6: Compute numerator: max(0, x + 0.2)
  // numerator = max(0, x + 0.2)
  // Step 7: Compute denominator: max(1, x + 0.5)
  // denominator = max(0, min(1, x + 0.5))
  // Actually, the formula is: hard_sigmoid(x) = clip((x + 0.5)/1.0, 0, 1)
  // So, divide numerator by denominator
  // But the standard hard sigmoid is: clip((x + 0.5), 0, 1)
