  func.func @main(%arg0: tensor<7x7xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x7xf32>) -> tensor<6x7xf32> {
    // Parameters:
    // %arg0: gemm.weight (tensor<7x7xf32>)
    // %arg1: gemm.bias (tensor<7xf32>)
    // %arg2: input tensor (tensor<6x7xf32>)

    // Step 1: GEMM: x = gemm(%arg2, %arg0^T) + bias
    // Transpose gemm.weight for proper matmul
    %weight_T = "stablehlo.transpose"(%arg0) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>
    // Dot general: input x weight^T
    %x_dot = "stablehlo.dot_general"(%arg2, %weight_T) {
      dot_dimension_numbers = #stablehlo.dot<lhs_batching_dimensions = [], rhs_batching_dimensions = [], lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>
    } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
    // Add bias
    %x_bias = "stablehlo.add"(%x_dot, %arg1) : (tensor<6x7xf32>, tensor<7xf32>) -> tensor<6x7xf32>

    // Step 2: Scale by scaling_factor (0.5)
    // Create constant for scaling factor
    %scale_const = "stablehlo.constant"() {value = dense<0.5> : tensor<f32>} : () -> tensor<f32>
    // Broadcast scale to shape of x
    %scale_bcast = "stablehlo.broadcast_in_dim"(%scale_const) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6x7xf32>
    // Element-wise multiply
    %scaled = "stablehlo.multiply"(%x_bias, %scale_bcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

    // Step 3: Hardtanh with min_val = -2, max_val = 2
    // Create constants for min and max
    %min_const = "stablehlo.constant"() {value = dense<-2.0> : tensor<f32>} : () -> tensor<f32>
    %max_const = "stablehlo.constant"() {value = dense<2.0> : tensor<f32>} : () -> tensor<f32>
    // Broadcast min and max to shape
    %min_bcast = "stablehlo.broadcast_in_dim"(%min_const) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6x7xf32>
    %max_bcast = "stablehlo.broadcast_in_dim"(%max_const) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6x7xf32>
    // Implement Hardtanh: clip between min and max
    // max(x, min_val)
    %clipped_min = "stablehlo.maximum"(%scaled, %min_bcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
    // min(x, max_val)
    %clipped = "stablehlo.minimum"(%clipped_min, %max_bcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

    // Step 4: GELU activation
    // GELU implementation via approximation: GELU(x) ≈ 0.5 * x * (1 + erf(x / sqrt(2)))
    // Compute x / sqrt(2)
    %sqrt2_const = "stablehlo.constant"() {value = dense<1.4142135623> : tensor<f32>} : () -> tensor<f32>
    %sqrt2_bcast = "stablehlo.broadcast_in_dim"(%sqrt2_const) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6x7xf32>
    %x_div_sqrt2 = "stablehlo.divide"(%clipped, %sqrt2_bcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
    // Compute erf(x / sqrt(2))
    %erf_x = "chlo.erf"(%x_div_sqrt2) : (tensor<6x7xf32>) -> tensor<6x7xf32>
    // Compute 1 + erf(...)
    %one_const = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
    %one_bcast = "stablehlo.broadcast_in_dim"(%one_const) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6x7xf32>
    %one_plus_erf = "stablehlo.add"(%one_bcast, %erf_x) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
    // Compute 0.5 * x
    %half_const = "stablehlo.constant"() {value = dense<0.5> : tensor<f32>} : () -> tensor<f32>
    %half_bcast = "stablehlo.broadcast_in_dim"(%half_const) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6x7xf32>
    %x_half = "stablehlo.multiply"(%clipped, %half_bcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
    // Final GELU output: 0.5 * x * (1 + erf(x / sqrt(2)))
    %gelu = "stablehlo.multiply"(%x_half, %one_plus_erf) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

