    // Constants for parameters
    %scaling_factor = "stablehlo.constant"() {value = dense<0.5> : tensor<f32>} : () -> tensor<f32>
    %hardtanh_min = "stablehlo.constant"() {value = dense<-2.0> : tensor<f32>} : () -> tensor<f32>
