    // Since in PyTorch, nn.Linear performs: input * weight^T + bias
    // But in StableHLO, dot_general with proper dimension numbers can do this.
    // For GEMM: input: [6,7], weight: [7,7], output: [6,7]
    // Use dot_general with batching dims empty, contracting dims: input's dim 1, weight's dim 0
    %batch_dim = 0 : i64
    %contract_dim = 1 : i64
    %gemm_result = "stablehlo.dot_general"(%arg2, %arg0) {
      dot_dimension_numbers = #stablehlo.dot<lhs_batching_dimensions = [], rhs_batching_dimensions = [], lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>
    } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

    // Step 2: Multiply by scaling factor
    %scaled = "stablehlo.multiply"(%gemm_result, %scaling_factor) : (tensor<6x7xf32>, tensor<f32>) -> tensor<6x7xf32>

    // Step 3: Hardtanh activation: clip between min and max
