    // %gemm_weight = %arg0 (parameter)
    // %gemm_bias = %arg1 (parameter)
    // Input: %arg2
    // Perform dot_general: (batch, in_features) x (out_features, in_features)^T
    // But in MLIR, the linear is typically implemented as dot_general with appropriate dimension numbers
    // For a linear layer: input shape [batch, in_features], weight shape [out_features, in_features]
    // We need to transpose weight to [in_features, out_features] for dot_general
    // But as per the description, %arg0 is weight, shape [7x7], so shape [out_features, in_features]
    // So, to do input x weight^T, we do dot_general with contracting dims: input's last dim, weight's last dim
    // Let's set up dot_general accordingly.

    // Transpose weight to shape [7,7] (no change), but for clarity, we can do transpose
    %weight_T = "stablehlo.transpose"(%arg0) {permutation = array<i64: 1, 0>} : tensor<7x7xf32> -> tensor<7x7xf32>

    // Dot general: input %arg2 [6x7], weight^T [7x7]
    // Contract over dimension 1 of input and 0 of weight_T
    %dot = "stablehlo.dot_general"(%arg2, %weight_T) {
      dot_dimension_numbers = #stablehlo.dot<lhs_batching_dimensions = [], rhs_batching_dimensions = [], lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>
    } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

    // Add bias
    // %arg1 shape: [7], need to broadcast to [6,7]
    %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {
      broadcast_dimensions = array<i64: 0>
    } : (tensor<7xf32>) -> tensor<6x7xf32>

    %add_bias = "stablehlo.add"(%dot, %bias_broadcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

    // Step 2: Scale by 0.5
    %const_scale = "stablehlo.constant"() {value = dense<0x3F000000> : tensor<f32>} : () -> tensor<f32> // 0.5 in hex
    // Broadcast scalar to shape [6,7]
    %scale_broadcast = "stablehlo.broadcast_in_dim"(%const_scale) {
      broadcast_dimensions = array<i64: 0>
    } : (tensor<f32>) -> tensor<6x7xf32>
    %scaled = "stablehlo.multiply"(%add_bias, %scale_broadcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

    // Step 3: Hardtanh with min -2, max 2
    // Constants for min and max
    %const_min = "stablehlo.constant"() {value = dense<0xC0000000> : tensor<f32>} : () -> tensor<f32> // -2
    %const_max = "stablehlo.constant"() {value = dense<0x40000000> : tensor<f32>} : () -> tensor<f32> // 2

    // Broadcast min and max to shape [6,7]
    %min_broadcast = "stablehlo.broadcast_in_dim"(%const_min) {
      broadcast_dimensions = array<i64: 0>
    } : (tensor<f32>) -> tensor<6x7xf32>
    %max_broadcast = "stablehlo.broadcast_in_dim"(%const_max) {
      broadcast_dimensions = array<i64: 0>
    } : (tensor<f32>) -> tensor<6x7xf32>

    // Compute hardtanh: clip between min and max
    %clipped_min = "stablehlo.maximum"(%scaled, %min_broadcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
    %clipped = "stablehlo.minimum"(%clipped_min, %max_broadcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

    // Step 4: GELU activation
    // GELU is approximated as: 0.5 * x * (1 + erf(x / sqrt(2)))
    // Compute x / sqrt(2)
