    %sqrt2_broadcast = "stablehlo.broadcast_in_dim"(%const_sqrt2) {
      broadcast_dimensions = array<i64: 0>
    } : (tensor<f32>) -> tensor<1x1xf32> // but shape scalar, so shape [1], broadcast to [6,7]
    // For simplicity, broadcast scalar to [6,7]
    %sqrt2_broadcast2 = "stablehlo.broadcast_in_dim"(%const_sqrt2) {
      broadcast_dimensions = array<i64: 0>
    } : (tensor<f32>) -> tensor<6x7xf32>

    // x / sqrt(2)
    %x_div_sqrt2 = "stablehlo.divide"(%clipped, %sqrt2_broadcast2) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

    // erf(x / sqrt(2))
    %erf_x = "chlo.erf"(%x_div_sqrt2) : (tensor<6x7xf32>) -> tensor<6x7xf32>

    // 1 + erf(...)
    %one_const = "stablehlo.constant"() {value = dense<0x3F800000> : tensor<f32>} : () -> tensor<f32> // 1.0
    %one_broadcast = "stablehlo.broadcast_in_dim"(%one_const) {
