    } : (tensor<f32>) -> tensor<6x7xf32>
    %one_plus_erf = "stablehlo.add"(%one_broadcast, %erf_x) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

