    %x_times = "stablehlo.multiply"(%clipped, %one_plus_erf) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

    // 0.5 * x * (1 + erf(...))
    %half_const = "stablehlo.constant"() {value = dense<0x3F000000> : tensor<f32>} : () -> tensor<f32>
    %half_broadcast2 = "stablehlo.broadcast_in_dim"(%half_const) {
