    %c_zero = stablehlo.constant dense<0.0> : tensor<f32>
    %c_divide_value = stablehlo.constant dense<1.0> : tensor<f32>
    // Extract shape constants
    %shape_b = stablehlo.constant dense<[6,7]> : tensor<2xi64>
