    // Compute matmul: %arg1 (7x7) x %arg5 (6x7) -> result shape [6,7]
    // For matmul, need to transpose %arg5 to [7,6] for proper multiplication
    %arg5_T = "stablehlo.transpose"(%arg5) {permutation = [1, 0]} : tensor<6x7xf32> -> tensor<7x6xf32>
    // Perform dot_general: %arg1 (7x7) x %arg5_T (7x6) -> [7,6]
    %dot_result = "stablehlo.dot_general"(%arg1, %arg5_T) {
      dot_dimension_numbers = #stablehlo.dot<lhs_batching_dimensions = [], rhs_batching_dimensions = [], lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>
    } : (tensor<7x7xf32>, tensor<7x6xf32>) -> tensor<7x6xf32>
    // Transpose dot result to shape [6,7]
    %matmul_out = "stablehlo.transpose"(%dot_result) {permutation = [1, 0]} : tensor<7x6xf32> -> tensor<6x7xf32>
    // Batch normalization: compute mean and variance over batch dimension (0)
    // Reduce mean
    %axes_batch = "stablehlo.constant" dense<[0]> : tensor<1xi64>
    %mean = "stablehlo.reduce"(%matmul_out, %c_zero) {
      dimensions = [0]
    } : (tensor<6x7xf32>, tensor<f32>) -> tensor<6x7xf32>
    // Compute squared difference
    %diff = "stablehlo.subtract"(%matmul_out, %mean) : tensor<6x7xf32>
    %diff_sq = "stablehlo.multiply"(%diff, %diff) : tensor<6x7xf32>
    // Reduce variance
    %var = "stablehlo.reduce"(%diff_sq, %c_zero) {
      dimensions = [0]
