  %pred_times_targets = "stablehlo.multiply"(%arg0, %targets_bcast) : (tensor<6x6xf32>, tensor<6x6xf32>) -> tensor<6x6xf32>

  // Step 3: Create tensor of ones for constant
  %one_const = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>

  // Step 4: Compute 1 - predictions * targets
  %one_minus_pred_targets = "stablehlo.subtract"(%one_const, %pred_times_targets) : (tensor<f32>, tensor<6x6xf32>) -> tensor<6x6xf32>

  // Step 5: Clamp the result at min=0
  // Since StableHLO does not have clamp, use maximum with 0
  %zero_const = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
