module {
  func.func @main(%arg0: tensor<6x7x8xf32>) -> tensor<6x7x9xf32> {
    // Constants for pooling parameters
    %c_kernel_size = constant 8 : index
    %c_stride = constant 1 : index
    %c_padding = constant 4 : index

    // Get input shape dimensions
    %input_shape = shape %arg0 : tensor<6x7x8xf32>
    %dim0 = tensor.dim %input_shape, 0 : tensor<6x7x8xf32> // batch size
    %dim1 = tensor.dim %input_shape, 1 : tensor<6x7x8xf32> // channels
    %dim2 = tensor.dim %input_shape, 2 : tensor<6x7x8xf32> // input length

    // Compute output length: output_length = floor((input_length + 2*padding - kernel_size)/stride) + 1
    // First, compute padded_input_length = input_length + 2*padding
    %two = constant 2 : index
    %pad_times_two = arith.mulf %c_padding, %two : index
    %padded_input_length = arith.addi %dim2, %pad_times_two : index

    // numerator = padded_input_length - kernel_size
    %numerator = arith.subi %padded_input_length, %c_kernel_size : index

    // quotient = floor(numerator / stride)
    %quotient = arith.floordivsi %numerator, %c_stride : index

    // output_length = quotient + 1
    %output_length = arith.addi %quotient, 1 : index

    // Compute the shape of the output tensor: [batch_size, channels, output_length]
    %out_shape = tensor.from_elements %dim0, %dim1, %output_length : tensor<3xindex>

    // Prepare for pooling: need to pad input tensor
    // Pad the input tensor on the last dimension (length) with padding on both sides
    // Padding: [[0,0], [0,0], [padding, padding]]
    %pad_low = constant 0 : index
    %pad_high = %c_padding : index
    %padding_config = tensor.from_elements %pad_low, %pad_high : tensor<2xindex>
    %padding_config_full = tensor.from_elements %padding_config, %padding_config : tensor<3xindex>

    // Pad the input tensor
    %padded_input = "stablehlo.pad"(%arg0, %padding_config_full) : (tensor<6x7x8xf32>, tensor<3x2xindex>) -> tensor<6x7x16xf32>

    // Now, perform strided window reduction (average pooling)
    // Use reduce_window with window size = kernel_size, stride = stride, padding = 0 (since already padded)
    // For average pooling, reduce with sum, then divide by kernel size

    // Define the window dimensions: [1, 1, kernel_size]
    %window_dims = tensor.from_elements 1, 1, %c_kernel_size : tensor<3xindex>
    // Strides: [1, 1, stride]
    %strides = tensor.from_elements 1, 1, %c_stride : tensor<3xindex>
    // Padding: zero padding for reduce_window (already padded input)
    %zero_padding = "stablehlo.constant"() : () -> tensor<3x2xindex>
    // For reduce_window, padding is specified as a tensor of pairs
    // Since input is already padded, set padding to zero
    // But reduce_window in StableHLO expects explicit padding; set to zeros
    // So, padding tensor of shape [3,2], all zeros
    // Use "stablehlo.constant" with zeros
    %pad_value = constant 0 : index
    %padding_for_reduce = "stablehlo.constant"() : () -> tensor<3x2xindex>
    // Create zero padding tensor
    %padding_vals = tensor.from_elements 0, 0, 0, 0, 0, 0 : tensor<6x2xindex>
    // Reshape to [3,2]
    // But easier: create a tensor of shape [3,2] with zeros
    %padding_tensor = "stablehlo.constant"() : () -> tensor<3x2xindex>
    // Actually, for simplicity, set padding to zero in reduce_window
    // (In StableHLO, reduce_window's padding is optional; default is zero)
    // So, omit explicit padding, as input is already padded

    // Perform reduce_window with sum
    %sum_result = "stablehlo.reduce_window"(%padded_input, %zero_padding, "add", %window_dims, %strides) : 
        (tensor<6x7x16xf32>, tensor<3x2xindex>, string, tensor<3xindex>, tensor<3xindex>) -> tensor<6x7x?xf32>

    // The output shape is [batch, channels, output_length], but the last dimension is dynamic
    // To get the output shape, we can use shape inference
    // For simplicity, assume the output shape is [dim0, dim1, output_length]

    // Divide sum by kernel size to get average
    // Create a tensor with value 1 / kernel_size
    %inv_kernel_size = arith.divf(1.0, "stablehlo.constant"() : () -> f32) : f32
    %inv_kernel_size_const = constant 0.125 : f32 // 1/8 = 0.125
    // Broadcast to shape of sum result
    // But since sum result shape is [batch, channels, output_length], broadcast scalar
    %avg = "stablehlo.broadcast_in_dim"(%inv_kernel_size_const, %sum_result) : (f32, tensor<6x7x?xf32>) -> tensor<6x7x?xf32>

    // Now, reshape the result to the expected output shape: [6,7,9]
    // The output length is computed as output_length
    // But in the problem, output shape is tensor<6x7x9xf32>
    // So, reshape sum result to shape [6,7,9]
    %final_shape = tensor.from_elements %dim0, %dim1, %output_length : tensor<3xindex>
    %output = "stablehlo.reshape"(%avg, %final_shape) : (tensor<6x7x?xf32>, tensor<3xindex>) -> tensor<6x7x9xf32>

    return %output : tensor<6x7x9xf32>
  }
