  func @main(%arg0: tensor<6x7xf32>) -> tensor<6x7xf32> {
    // Define constants for 1.0 and 0.0
    %c_one = stablehlo.constant dense<1.0> : tensor<f32>
    %c_zero = stablehlo.constant dense<0.0> : tensor<f32>

    // Compute sigmoid(x) = 1 / (1 + exp(-x))
