    %exp_neg_x = stablehlo.exponential %neg_x : tensor<6x7xf32>
    %denominator = stablehlo.add %c_one, %exp_neg_x : tensor<6x7xf32>
    %sigmoid_x = stablehlo.divide %c_one, %denominator : tensor<6x7xf32>

    // Compute x * sigmoid(x)
    %output = stablehlo.multiply %arg0, %sigmoid_x : tensor<6x7xf32>

    return %output : tensor<6x7xf32>
  }
