    } : (tensor<6x7x8x8xf32>, tensor<2xi64>) -> tensor<6x7x8x8xf32>

    // Compute variance: E[(x - mean)^2]
    // Broadcast mean to shape of input
    %mean_bcast = "mhlo.broadcast_in_dim"(%mean) {
      broadcast_dimensions = dense<[2, 3]> : tensor<2xi64>
    } : (tensor<6x7x8x8xf32>) -> tensor<6x7x8x8xf32>
