    %var_plus_eps = "mhlo.add"(%var, %epsilon) : (tensor<6x7x8x8xf32>, tensor<f32>) -> tensor<6x7x8x8xf32>
    %stddev = "mhlo.sqrt"(%var_plus_eps) : (tensor<6x7x8x8xf32>) -> tensor<6x7x8x8xf32>

