    %conv = "stablehlo.convolution"(%arg2, %arg0) {
      window_strides = dense<2, 2>,
      padding = dense<1, 1, 1, 1>,
      lhs_dilation = dense<1, 1, 1, 1>,
      rhs_dilation = dense<1, 1, 1, 1>,
