      batch_group_count = 1,
      precision_config = null
    } : (tensor<6x7x6x6xf32>, tensor<7x7x3x3xf32>) -> tensor<6x7x12x12xf32>
    // Step 2: Mish activation: x * tanh(softplus(x))
    // Compute softplus: log(1 + exp(x))
    %exp_x = "stablehlo.exponential"(%conv) : tensor<6x7x12x12xf32>
    %one = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
    %add = "stablehlo.add"(%exp_x, %one) : tensor<6x7x12x12xf32>
    %softplus = "stablehlo.log"(%add) : tensor<6x7x12x12xf32>
    // tanh(softplus)
    %tanh_sp = "stablehlo.tanh"(%softplus) : tensor<6x7x12x12xf32>
    // Element-wise multiply: x * tanh(softplus(x))
    %mish = "stablehlo.multiply"(%conv, %tanh_sp) : tensor<6x7x12x12xf32>
    // Step 3: Add bias
    // Broadcast bias to shape
    %bias_bcast = "stablehlo.broadcast_in_dim"(%arg1) {
      broadcast_dimensions = dense<1> // broadcast along dimension 1
    } : (tensor<7xf32>) -> tensor<6x7xf32>
    // Expand bias to match shape
