    %add_bias = "stablehlo.add"(%mish, %bias_broadcasted) : tensor<6x7x12x12xf32>
    // Step 4: Hardtanh activation: clamp between -1 and 1
    %minus_one = "stablehlo.constant"() {value = dense<-1.0> : tensor<f32>} : () -> tensor<f32>
