    // Expand bias to match 4D shape
    %bias_reshaped = "stablehlo.reshape"(%bias_bcast) : (tensor<6x7xf32>) -> tensor<6x7x1x1xf32>
    // Broadcast bias to full shape
    %bias_broadcasted = "stablehlo.broadcast_in_dim"(%bias_reshaped) {
      broadcast_dimensions = array<i64: 1, 2, 3>
    } : (tensor<6x7x1x1xf32>) -> tensor<6x7x12x12xf32>
    // Add bias
    %add_bias = "stablehlo.add"(%mish, %bias_broadcasted) : (tensor<6x7x12x12xf32>, tensor<6x7x12x12xf32>) -> tensor<6x7x12x12xf32>

    // Step 4: Apply Hardtanh activation with min -1, max 1
    // hardtanh(x) = max(min(x, 1), -1)
