    // out = torch.nn.functional.scaled_dot_product_attention(Q, K, V)
    // which computes:
    //   attn_weights = softmax((Q @ K^T) / sqrt(d_k))
    //   output = attn_weights @ V

    // Step 1: Transpose K for matmul
    %k_transposed = "mhlo.transpose"(%arg1) {permutation = dense<[0,1,3,2]>} : tensor<6x6x7x8xf32> -> tensor<6x6x8x7xf32>

    // Step 2: Compute Q @ K^T
    %matmul_qk = "mhlo.dot_general"(%arg0, %k_transposed) {
      dot_dimension_numbers = {
        lhs_contracting_dimensions = dense<[2]> : tensor<1xi64>,
        rhs_contracting_dimensions = dense<[3]> : tensor<1xi64>,
        lhs_batch_dimensions = dense<[0,1]> : tensor<2xi64>,
        rhs_batch_dimensions = dense<[0,1]> : tensor<2xi64>
      },
      precision_config = {use_default_precision = true}
    } : tensor<6x6x7x7xf32>

    // Step 3: Scale by 1/sqrt(d_k), with d_k=8
