    // For softmax, compute max for numerical stability
    %max_reduce = "mhlo.reduce"(%scaled_qk, %initial_max = "mhlo.constant"() {value = dense_f32< -inf >}) {
      dimensions = dense<[3]> : tensor<1xi64>,
      reduction = "max"
    } : tensor<6x6x7xf32>

    // Broadcast max for subtraction
    %max_bcast = "mhlo.broadcast_in_dim"(%max_reduce) {
      broadcast_dimensions = dense<[0,1,2]> : tensor<3xi64>
    } : tensor<6x6x7xf32>

    // Subtract max for numerical stability
    %shifted_logits = "mhlo.sub"(%scaled_qk, %max_bcast) : tensor<6x6x7x7xf32>

    // Exponentiate
    %exp_logits = "mhlo.exp"(%shifted_logits) : tensor<6x6x7x7xf32>

