    // The reduction outputs shape: [16]
    // To broadcast back, reshape to [16,1]
    %mean_reshaped = "stablehlo.reshape"(%mean) : (tensor<16xf32>) -> tensor<16x1xf32>

    // Compute variance
    // Subtract mean
    %x_minus_mean = "stablehlo.subtract"(%fc_bias, "stablehlo.broadcast_in_dim"(%mean_reshaped) {broadcast_dimensions = array<i64: 1>}) : tensor<16x16xf32>, tensor<16x1xf32> -> tensor<16x16xf32>
    // Square
