    // Step 3: Compute element-wise division: log_pred / target
    %div1 = stablehlo.divide %log_arg0, %broadcast_arg1 : tensor<12x12xf32>

    // Step 4: Reduce along all dimensions to compute mean
    // Initialize reduction with 0.0
    %init = stablehlo.constant dense<0.0> : tensor<f32>
    // Reduce over dimensions 0 and 1
    %reduced = stablehlo.reduce %div1, %init
