      window_strides = array<i64: 1, 1, 1>,
      padding = dense<[[1, 1], [1, 1], [1, 1]]> : tensor<3x2xi64>,
      lhs_dilation = array<i64: 1, 1, 1>,
      rhs_dilation = array<i64: 1, 1, 1>,
      dimension_numbers = #stablehlo.conv<[b, d, h, w, c]x[co, ci, kd, kh, kw]->[b, co, oh, ow, d]>,
      feature_group_count = 1 : i64,
      batch_group_count = 1 : i64
    } (%arg4, %arg2) : (tensor<6x3x16x7x7xf32>, tensor<16x3x3x3xf32>) -> tensor<6x16x14x5x5xf32>

    // Step 2: Scale by scaling_factor (%arg0)
    %scaled = "stablehlo.multiply"(%conv, %arg0) : (tensor<6x16x14x5x5xf32>, tensor<16xf32>) -> tensor<6x16x14x5x5xf32>

    // Step 3: Tanh activation
    %tanh = "stablehlo.tanh"(%scaled) : tensor<6x16x14x5x5xf32>

    // Step 4: Multiply by bias (%arg3)
    %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg3) {
      broadcast_dimensions = array<i64: 0>
    } : (tensor<16xf32>) -> tensor<6x16x14x5x5xf32>
    %biased = "stablehlo.multiply"(%tanh, %bias_broadcast) : (tensor<6x16x14x5x5xf32>, tensor<6x16x14x5x5xf32>) -> tensor<6x16x14x5x5xf32>

    // Step 5: Sigmoid activation
    %neg_biased = "stablehlo.negate"(%biased) : tensor<6x16x14x5x5xf32>
    %exp_neg_biased = "stablehlo.exponential"(%neg_biased) : tensor<6x16x14x5x5xf32>
    %one = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
    %denominator = "stablehlo.add"(%one, %exp_neg_biased) : (tensor<f32>, tensor<f32>) -> tensor<f32>
    %sigmoid = "stablehlo.divide"(%one, %denominator) : (tensor<f32>, tensor<f32>) -> tensor<f32>

    // Output is %sigmoid
    return %sigmoid : tensor<6x16x14x5x5xf32>
  }
