    // For that, reduce over last dimension
    %mean_reduce = "stablehlo.reduce"(%x_reshaped, %zero) ({
      ins = (acc, val) -> "stablehlo.add"(%acc, %val) : f32, f32 -> f32
      outs = (result) -> result
    }) : tensor<14x16x256> -> tensor<14x16xf32>

