    %y = "stablehlo.add"(%scaled, %bias_bcast) : tensor<14x16x16x16xf32> , tensor<1x16x1x1xf32> -> tensor<14x16x16x16xf32>

    // Return the normalized, affine-transformed tensor
    return %y : tensor<14x16x16x16xf32>
  }
