func.func @main(%x: tensor<7x3xf32>) -> tensor<7x3xf32> {
  %zero = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
  // Compute x^2
  %x_squared = "stablehlo.multiply"(%x, %x) : (tensor<7x3xf32>, tensor<7x3xf32>) -> tensor<7x3xf32>
  // Sum over k (dimension 1) to get sum_k x[i,k]^2
  %sum_squares = "stablehlo.reduce"(%x_squared, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>): tensor<f32> {
      %s = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%s) : (tensor<f32>) -> ()
    }
  }) {dimensions = array<i64: 1>} : (tensor<7x3xf32>, tensor<f32>) -> tensor<7x1xf32>
  // Broadcast sum to shape 7x3
  %sum_broadcast = "stablehlo.broadcast_in_dim"(%sum_squares) {broadcast_dimensions = array<i64: 1>} : (tensor<7x1xf32>) -> tensor<7x3xf32>
  // Compute sqrt of sum_k x[i,k]^2
  %norm = "stablehlo.sqrt"(%sum_broadcast) : (tensor<7x3xf32>) -> tensor<7x3xf32>
  // Divide x by norm
  %out = "stablehlo.divide"(%x, %norm) : (tensor<7x3xf32>, tensor<7x3xf32>) -> tensor<7x3xf32>
  return %out : tensor<7x3xf32>
}
