// StableHLO program implementing the described model forward pass
module {
  func.func @main(%arg0: tensor<16x16xf32>, %arg1: tensor<16xf32>, %arg2: tensor<16xf32>, %arg3: tensor<16xf32>, %arg4: tensor<16x16xf32>) -> tensor<16x16xf32> {
    // Constants for parameters
    %c_in_features = "stablehlo.constant"() {value = dense<16> : tensor<16xi32>} : () -> tensor<16xi32>
    %c_out_features = "stablehlo.constant"() {value = dense<16> : tensor<16xi32>} : () -> tensor<16xi32>
    %c_num_groups = "stablehlo.constant"() {value = dense<16> : tensor<16xi32>} : () -> tensor<16xi32>
    %c_hardtanh_min = "stablehlo.constant"() {value = dense<1> : tensor<1xf32>} : () -> tensor<1xf32>
    %c_hardtanh_max = "stablehlo.constant"() {value = dense<1> : tensor<1xf32>} : () -> tensor<1xf32>

    // Load parameters
    %in_features = "stablehlo.convert"(%arg0) : (tensor<16xf32>) -> tensor<16xi32>
    // For simplicity, assume parameters are passed as tensors matching their shapes
    // but in practice, they are constants or parameters; here, we treat them as inputs
    // so we just use %arg0, %arg1, etc., directly as parameters.

    // Extract parameters from arguments
    // For the purpose of this code, assume:
    // %gemm_weight = %arg0 (tensor<16x16xf32>)
    // %gemm_bias = %arg1 (tensor<16xf32>)
    // %group_norm_weight = %arg2 (tensor<16xf32>)
    // %group_norm_bias = %arg3 (tensor<16xf32>)
    // %input = %arg4 (tensor<16x16xf32>)

    // Step 1: GEMM (matrix multiplication)
    // "stablehlo.dot_general" with batch dims empty, contracting dims [1] of input and [0] of weight
    // input shape: [16,16], weight shape: [16,16]
    // Contract over dimension 1 of input and 0 of weight
    %gemm = "stablehlo.dot_general"(%arg4, %arg0) {
      dot_dimension_numbers = #stablehlo.dot<lhs_batching_dimensions = [], rhs_batching_dimensions = [], lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>
    } : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

    // Step 2: Add bias
    // Broadcast bias to shape [16,16]
    %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {
      broadcast_dimensions = array<i64: 1>
    } : (tensor<16xf32>) -> tensor<16x16xf32>
    %gemm_bias_added = "stablehlo.add"(%gemm, %bias_broadcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

    // Step 3: Layer normalization (GroupNorm)
    // GroupNorm: normalize over features, with parameters gamma and beta
    // Compute mean over features (dim=1)
    // For simplicity, compute mean and variance manually
    // sum over dim=1
    %reduction_dims = array<i64: 1>
    // sum
    %sum = "stablehlo.reduce"(%gemm_bias_added, %c_zero) ({
      ^bb0(%a: tensor<16x16xf32>, %b: tensor<f32>): %s = "stablehlo.add"(%a, %b) : (tensor<16x16xf32>, tensor<f32>) -> tensor<16x16xf32>
      "stablehlo.return"(%s) : (tensor<16x16xf32>) -> ()
    }) {dimensions = %reduction_dims} : (tensor<16x16xf32>, tensor<f32>) -> tensor<16x16xf32>
    // Compute mean
    // total elements per feature: 16
    %elem_count = "stablehlo.constant"() {value = dense<16> : tensor<16xi32>} : () -> tensor<16xi32>
    %mean = "stablehlo.divide"(%sum, "stablehlo.convert"(%elem_count) : (tensor<16xi32>) -> tensor<16xf32>) : (tensor<16x16xf32>, tensor<16xf32>) -> tensor<16x16xf32>
    // Compute variance
    // subtract mean
    %mean_broadcast = "stablehlo.broadcast_in_dim"(%mean) {
      broadcast_dimensions = array<i64: 1>
    } : (tensor<16x16xf32>) -> tensor<16x16xf32>
    %diff = "stablehlo.subtract"(%gemm_bias_added, %mean_broadcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
    // square diff
    %diff_squared = "stablehlo.multiply"(%diff, %diff) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
    // sum squared diff
    %sum_sq = "stablehlo.reduce"(%diff_squared, %c_zero) ({
      ^bb1(%a: tensor<16x16xf32>, %b: tensor<f32>): %s = "stablehlo.add"(%a, %b) : (tensor<16x16xf32>, tensor<f32>) -> tensor<16x16xf32>
      "stablehlo.return"(%s) : (tensor<16x16xf32>) -> ()
    }) {dimensions = %reduction_dims} : (tensor<16x16xf32>, tensor<f32>) -> tensor<16x16xf32>
    // variance
    %variance = "stablehlo.divide"(%sum_sq, "stablehlo.convert"(%elem_count) : (tensor<16xi32>) -> tensor<16xf32>) : (tensor<16x16xf32>, tensor<16xf32>) -> tensor<16x16xf32>
    // epsilon for numerical stability
    %epsilon = "stablehlo.constant"() {value = dense<1.1920929e-7 : f32>} : () -> tensor<f32>
    // stddev = sqrt(variance + epsilon)
    %variance_plus_epsilon = "stablehlo.add"(%variance, %epsilon) : (tensor<16x16xf32>, tensor<f32>) -> tensor<16x16xf32>
    %stddev = "stablehlo.sqrt"(%variance_plus_epsilon) : (tensor<16x16xf32>) -> tensor<16x16xf32>
    // Normalize
    %normalized = "stablehlo.divide"(%diff, %stddev) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
    // Broadcast gamma and beta
    %gamma_broadcast = "stablehlo.broadcast_in_dim"(%arg2) {
      broadcast_dimensions = array<i64: 1>
    } : (tensor<16xf32>) -> tensor<16x16xf32>
    %beta_broadcast = "stablehlo.broadcast_in_dim"(%arg3) {
      broadcast_dimensions = array<i64: 1>
    } : (tensor<16xf32>) -> tensor<16x16xf32>
    // scale and shift
    %scaled = "stablehlo.multiply"(%normalized, %gamma_broadcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
    %shifted = "stablehlo.add"(%scaled, %beta_broadcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

    // Step 4: HardTanh activation
    // min constant
    %min_const = "stablehlo.broadcast_in_dim"(%c_hardtanh_min) {
      broadcast_dimensions = array<i64: 0>
    } : (tensor<1xf32>) -> tensor<16x16xf32>
    // max constant
    %max_const = "stablehlo.broadcast_in_dim"(%c_hardtanh_max) {
      broadcast_dimensions = array<i64: 0>
