    // Compute threshold tensor: threshold = constant 1.0
    %one_const = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>

    // Compute absolute difference minus 1: abs_diff_minus_one = abs_diff - 1
    %abs_diff_minus_one = "stablehlo.subtract"(%abs_diff, %one_const) : (tensor<6x6xf32>, tensor<f32>) -> tensor<6x6xf32>

    // Compute condition: abs_diff <= 1.0
    %cond = "stablehlo.compare"(%abs_diff, %one_const) {comparison_direction = #stablehlo<comparison_direction LT>, compare_type = #stablehlo<compare_type FLOAT>} : (tensor<6x6xf32>, tensor<6x6xf32>) -> tensor<6x6xi1>

    // Compute squared term: sq_term = 0.5 * sq_diff
