    %sq_term = "stablehlo.multiply"(%half_const, %sq_diff) : (tensor<f32>, tensor<f32>) -> tensor<f32>

    // Compute linear term: linear_term = abs_diff - 0.5
    %half_const2 = "stablehlo.constant"() {value = dense<0.5> : tensor<f32>} : () -> tensor<f32>
    %linear_term = "stablehlo.subtract"(%abs_diff, %half_const2) : (tensor<6x6xf32>, tensor<f32>) -> tensor<6x6xf32>

