    %loss_elementwise = "stablehlo.select"(%cond, %sq_term, %linear_term) : (tensor<6x6xi1>, tensor<6x6xf32>, tensor<6x6xf32>) -> tensor<6x6xf32>

    // Compute mean of the loss elements
