    %shape_conv_val = "tensor.extract" %shape_conv[2] : tensor<4xi64> -> i64
    %shape_conv_val3 = "tensor.extract" %shape_conv[3] : tensor<4xi64> -> i64
    // Compute mean over dims 2 and 3
    // For simplicity, perform reduction over dims 2 and 3
    %reduced_dim2 = "reduce"(%conv, %c0) {body = (x, c) -> (reduce_body)} : (tensor<16x7x10x10xf32>, tensor<i1>) -> tensor<16x7x1x1xf32>
    // But since reduction over dims 2 and 3, do two reductions
    // First reduce over dim 3
    %reduce_dim3 = "reduce"(%conv, %c0) {body = (x, c) -> (x + c)} : (tensor<16x7x10x10xf32>, tensor<i1>) -> tensor<16x7x10x1xf32>
    // Then reduce over dim 2
    %avg_pool = "reduce"(%reduce_dim3, %c0) {body = (x, c) -> (x + c)} : (tensor<16x7x10x1xf32>, tensor<i1>) -> tensor<16x7x1x1xf32>
    // Divide by number of elements (10*10=100)
    %div_const = "constant"() {value = dense<100.0> : tensor<f32>} : () -> tensor<f32>
    %avg = "elementwise.div"(%avg_pool, %div_const) : (tensor<16x7x1x1xf32>, tensor<f32>) -> tensor<16x7x1x1xf32>

    // Step 3: Add bias (%arg2) of shape (7)
    // Broadcast bias to shape (16x7x1x1)
    %bias_bcast = "broadcast_in_dim"(%arg2) {broadcast_dimensions = dense<[1, 0, 2, 3]>} : (tensor<7xf32>) -> tensor<16x7x1x1xf32>
    %add_bias = "elementwise.add"(%avg, %bias_bcast) : (tensor<16x7x1x1xf32>, tensor<16x7x1x1xf32>) -> tensor<16x7x1x1xf32>

    // Step 4: LogSumExp over dim 1 (channel dimension)
    // For LogSumExp, compute max over dim 1
    %max_over_channels = "reduce"(%add_bias, %c0) {body = (x, c) -> (max(x, c))} : (tensor<16x7x1x1xf32>, tensor<i1>) -> tensor<16x1x1xf32>
    // Subtract max for numerical stability
    %broadcast_max = "broadcast_in_dim"(%max_over_channels) {broadcast_dimensions = dense<[1, 2, 3]>} : (tensor<16x1x1xf32>) -> tensor<16x7x1x1xf32>
    %sub_max = "elementwise.sub"(%add_bias, %broadcast_max) : (tensor<16x7x1x1xf32>, tensor<16x1x1xf32>) -> tensor<16x7x1x1xf32>
