    %softplus = "stablehlo.log"(%stablehlo.add(%one_broadcast, %exp_x)) : tensor<6x7x6x6>

    // Compute tanh(softplus)
    %tanh_sp = "stablehlo.tanh"(%softplus) : tensor<6x7x6x6>

