                   %arg3: tensor<7xf32>,       // bn.weight
                   %arg4: tensor<7xf32>,       // bn.bias
                   %arg5: tensor<6x7xf32>) -> tensor<6x7xf32> { // input
    // Step 1: Compute gemm: x = input @ weight^T + bias
    // input: [6,7], weight: [7,7]
    %input = %arg5 : tensor<6x7xf32>
    %weight = %arg1 : tensor<7x7xf32>
    %bias = %arg2 : tensor<7xf32>
    // Transpose weight for matmul: [7,7] -> [7,7], but in StableHLO, dot_general with contracting dims
    // will handle this; specify dimension_numbers accordingly.
    %dimension_numbers = "{" 
                          "lhs_contracting_dims = [1], "
                          "rhs_contracting_dims = [0], "
                          "lhs_batch_dims = [], "
                          "rhs_batch_dims = []"
                        "}"
    %gemm_result = "stablehlo.dot_general"(%input, %weight, %dimension_numbers) : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
    // Add bias
    // bias: [7], need to broadcast to [6,7]
    %bias_bcast = "stablehlo.broadcast_in_dim"(%bias, dense<6,7> : tensor<6x7xf32>, dense<[0,1]> : tensor<2>) : tensor<6x7xf32>
    %gemm_bias = "stablehlo.add"(%gemm_result, %bias_bcast) : tensor<6x7xf32>

    // Step 2: Scale: element-wise multiply by scale parameter
    // scale: [7], broadcast to [6,7]
    %scale_bcast = "stablehlo.broadcast_in_dim"(%arg0, dense<6,7> : tensor<6x7xf32>, dense<[0,1]> : tensor<2>) : tensor<6x7xf32>
    %scaled = "stablehlo.multiply"(%gemm_bias, %scale_bcast) : tensor<6x7xf32>

    // Step 3: Batch normalization
    // batch norm: input: [6,7], parameters: weight and bias
    // For training mode, compute mean and variance over batch (dim 0)
    // Compute mean over batch
    %zero = "stablehlo.constant"() : () -> tensor<1x7xf32>
    %mean_reduce = "stablehlo.reduce"(%scaled, %zero, "add", dense<1> : tensor<1>) : tensor<1x7xf32>
    // Divide by batch size (6)
    %batch_size_const = "stablehlo.constant"() : () -> tensor<1xf32>
    %batch_size_value = "stablehlo.constant"() : () -> tensor<1xf32> {value = dense<6.0> : tensor<1xf32>}
    %mean = "stablehlo.divide"(%mean_reduce, %batch_size_value) : tensor<1x7xf32>
    // Compute variance
    // Subtract mean from each element
    %mean_bcast = "stablehlo.broadcast_in_dim"(%mean, dense<6,7> : tensor<6x7xf32>, dense<[0,1]> : tensor<2>) : tensor<6x7xf32>
    %diff = "stablehlo.subtract"(%scaled, %mean_bcast) : tensor<6x7xf32>
    // Square the differences
    %diff_sq = "stablehlo.multiply"(%diff, %diff) : tensor<6x7xf32>
    // Sum over batch
    %diff_sq_reduce = "stablehlo.reduce"(%diff_sq, %zero, "add", dense<1> : tensor<1>) : tensor<1x7xf32>
    // Variance = sum / (batch_size)
    %var = "stablehlo.divide"(%diff_sq_reduce, %batch_size_value) : tensor<1x7xf32>
    // Add epsilon for numerical stability
    %epsilon = "stablehlo.constant"() : () -> tensor<1x7xf32> {value = dense<1e-5 : f32> : tensor<1xf32>}
    %var_eps = "stablehlo.add"(%var, %epsilon) : tensor<1x7xf32>
    // Compute rsqrt of variance + epsilon
    %rsqrt_var = "stablehlo.rsqrt"(%var_eps) : tensor<1x7xf32>
    // Broadcast rsqrt to [6,7]
    %rsqrt_bcast = "stablehlo.broadcast_in_dim"(%rsqrt_var, dense<6,7> : tensor<6x7xf32>, dense<[0,1]> : tensor<2>) : tensor<6x7xf32>
    // Normalize: (x - mean) * rsqrt
    %norm = "stablehlo.multiply"(%diff, %rsqrt_bcast) : tensor<6x7xf32>

    // Step 4: Scale normalized output with bn.weight and add bn.bias
    // bn.weight: [7], broadcast
    %bn_weight_bcast = "stablehlo.broadcast_in_dim"(%arg3, dense<6,7> : tensor<6x7xf32>, dense<[0,1]> : tensor<2>) : tensor<6x7xf32>
    %scaled_norm = "stablehlo.multiply"(%norm, %bn_weight_bcast) : tensor<6x7xf32>
    // bn.bias: [7], broadcast
    %bn_bias_bcast = "stablehlo.broadcast_in_dim"(%arg4, dense<6,7> : tensor<6x7xf32>, dense<[0,1]> : tensor<2>) : tensor<6x7xf32>
    // Final output
    %output = "stablehlo.add"(%scaled_norm, %bn_bias_bcast) : tensor<6x7xf32>

    // Return the output tensor
    return %output : tensor<6x7xf32>
  }
