    // Use broadcast_in_dim with broadcast_dimensions = [0,1,2,3]
    %bias_bcast2 = "stablehlo.broadcast_in_dim"(%bias_bcast) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<16x1x1x1>) -> tensor<3x16x1x1x1>
