    %add_bias = "stablehlo.add"(%avg, %bias_bcast2) : (tensor<3x16x1x1x1>, tensor<3x16x1x1x1>) -> tensor<3x16x1x1x1>

    // Step 6: Sum along dimension 1 (the sum_dim)
    // sum_dim = 1
    // Initialize with zero
    %zero = "stablehlo.constant"() {value = dense<0x00000000> : tensor<f32>} : () -> tensor<f32>
