    // Step 1: Convolution parameters
    // %arg0: conv.weight (tensor<6x7x3x3xf32>)
    // %arg1: conv.bias (tensor<6xf32>)
    // %arg2: input tensor (tensor<6x7x6x6xf32>)

    // Step 2: Perform convolution
    %conv_result = "stablehlo.convolution"(%arg2, %arg0) {
      window_strides = array<i64: 1, 1>,
      padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
      lhs_dilation = array<i64: 1, 1>,
      rhs_dilation = array<i64: 1, 1>,
      dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>,
      feature_group_count = 1 : i64,
      batch_group_count = 1 : i64
    } : (tensor<6x7x3x3xf32>, tensor<6x7x3x3xf32>) -> tensor<6x6x4x4xf32>

    // Step 3: Add bias
    // Broadcast bias to match convolution output shape
    // %bias_broadcasted = broadcast bias to shape of %conv_result
    // bias shape: (6), conv output shape: (6,6,4,4)
    // broadcast bias along dimensions 1,2,3
    %bias_broadcasted = "stablehlo.broadcast_in_dim"(%arg1) {
      broadcast_dimensions = array<i64: 0>
    } : (tensor<6xf32>) -> tensor<6x6x4x4xf32>
    // The above broadcast_in_dim is insufficient; need to specify broadcast_dimensions
    // For broadcasting bias of shape [6] to [6,6,4,4], broadcast_dimensions = [0]
    // But to broadcast bias along all other dims, need to reshape bias to [6,1,1,1], then broadcast
    // So, first reshape bias to [6,1,1,1]
    %bias_reshaped = "stablehlo.reshape"(%arg1) {
      shape = tensor<6x1x1x1>
    } : (tensor<6xf32>) -> tensor<6x1x1x1>
    // Broadcast bias to shape [6,6,4,4]
    %bias_broadcasted = "stablehlo.broadcast_in_dim"(%bias_reshaped) {
      broadcast_dimensions = array<i64: 0, 1, 2, 3>
    } : (tensor<6x1x1x1>) -> tensor<6x6x4x4xf32>

    // Add bias
    %biased_conv = "stablehlo.add"(%conv_result, %bias_broadcasted) : (tensor<6x6x4x4xf32>, tensor<6x6x4x4xf32>) -> tensor<6x6x4x4xf32>

    // Step 4: Apply Instance Normalization
    // InstanceNorm2d: normalize over spatial dims (2,3), per batch and channel
    // Compute mean over dims 2,3
    // For mean: reduce over dims 2,3
    %init_mean = "stablehlo.constant"() {value = dense<0.0> } : () -> tensor<f32>
    %mean = "stablehlo.reduce"(%biased_conv, %init_mean) {
      dimensions = array<i64: 2, 3>,
      body = ^bb0(%a: tensor<f32>, %b: tensor<f32>) -> (tensor<f32>) {
        %sum = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
        "stablehlo.return"(%sum) : (tensor<f32>) -> ()
      }
    } : (tensor<6x6x4x4xf32>, tensor<f32>) -> tensor<6x6x4x4xf32>
    // Compute number of elements in spatial dims: 4*4=16
    %spatial_size = "stablehlo.constant"() {value = dense<16> } : () -> tensor<i32>
    // Convert mean sum to float
    // But sum is float, divide by 16
    %mean_divisor = "stablehlo.convert"(%spatial_size) : (tensor<i32>) -> tensor<f32>
    %mean_value = "stablehlo.divide"(%mean, %mean_divisor) : (tensor<f32>, tensor<f32>) -> tensor<f32>
    // Reshape mean to broadcast over spatial dims
    %mean_broadcast = "stablehlo.reshape"(%mean_value) {
      shape = tensor<6x6x1x1>
    } : (tensor<6x6x4x4xf32>) -> tensor<6x6x1x1>
    // Broadcast mean over spatial dims
    %mean_broadcasted = "stablehlo.broadcast_in_dim"(%mean_broadcast) {
      broadcast_dimensions = array<i64: 0, 1, 2, 3>
    } : (tensor<6x6x1x1>) -> tensor<6x6x4x4xf32>
    // Compute variance: (x - mean)^2, then mean of squared differences
    // x - mean
    %x_minus_mean = "stablehlo.subtract"(%biased_conv, %mean_broadcasted) : (tensor<6x6x4x4xf32>, tensor<6x6x4x4xf32>) -> tensor<6x6x4x4xf32>
    // Square
    %diff_squared = "stablehlo.multiply"(%x_minus_mean, %x_minus_mean) : (tensor<6x6x4x4xf32>, tensor<6x6x4x4xf32>) -> tensor<6x6x4x4xf32>
    // Sum squared differences over spatial dims
    %sum_sq_diff = "stablehlo.reduce"(%diff_squared, %init_mean) {
      dimensions = array<i64: 2, 3>,
      body = ^bb1(%a: tensor<f32>, %b: tensor<f32>) -> (tensor<f32>) {
        %s = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
        "stablehlo.return"(%s) : (tensor<f32>) -> ()
      }
    } : (tensor<6x6x4x4xf32>, tensor<f32>) -> tensor<6x6x4x4xf32>
    // Variance = sum / 16
    %variance = "stablehlo.divide"(%sum_sq_diff, %mean_divisor) : (tensor<f32>, tensor<f32>) -> tensor<f32>
    // Compute stddev = sqrt(variance + epsilon)
    // epsilon = small float, e.g., 1e-5
    %epsilon = "stablehlo.constant"() {value = dense<0x3B9AC9F0> } : () -> tensor<f32> // 1e-5 in hex
    %var_plus_epsilon = "stablehlo.add"(%variance, %epsilon) : (tensor<f32>, tensor<f32>) -> tensor<f32>
    %stddev = "stablehlo.sqrt"(%var_plus_epsilon) : (tensor<f32>) -> tensor<f32>
    // Normalize: (x - mean) / stddev
    %normalized = "stablehlo.divide"(%x_minus_mean, %stddev) : (tensor<6x6x4x4xf32>, tensor<6x6x4x4xf32>) -> tensor<6x6x4x4xf32>

    // Step 5: Divide by divide_by scalar (2.0)
    // Create constant 2.0
    %divisor_const = "stablehlo.constant"() {value = dense<0x40000000> } : () -> tensor<f32> // 2.0 in hex
    %output = "stablehlo.divide"(%normalized, %divisor_const) : (tensor<6x6x4x4xf32>, tensor<f32>) -> tensor<6x6x4x4xf32>

    // Return the final tensor
    "stablehlo.return"(%output) : (tensor<6x6x4x4xf32>) -> ()
  }
