      window_strides = array<i64: 1, 1>,
      padding = dense<[[1, 1], [1, 1]]> : tensor<2x2xi64>,
      lhs_dilation = array<i64: 1, 1>,
      rhs_dilation = array<i64: 1, 1>,
      dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>,
      feature_group_count = 1 : i64,
      batch_group_count = 1 : i64
    } : (tensor<6x7x6x6xf32>, tensor<6x7x3x3xf32>) -> tensor<6x6x4x4xf32>

    // Step 2: Add bias
    // Broadcast bias to shape of conv output
    %bias_bcast = "stablehlo.broadcast_in_dim"(%arg1) {
      broadcast_dimensions = array<i64: 0>
    } : (tensor<6xf32>) -> tensor<6x1x1x1xf32>

    // Reshape bias to shape for broadcasting
    %bias_reshaped = "stablehlo.reshape"(%bias_bcast) : (tensor<6xf32>) -> tensor<6x1x1x1xf32>

    // Broadcast bias to full shape
    %bias_broadcasted_full = "stablehlo.broadcast_in_dim"(%bias_reshaped) {
      broadcast_dimensions = array<i64: 0, 1, 2, 3>
    } : (tensor<6x1x1x1xf32>) -> tensor<6x6x4x4xf32>

    // Add bias
    %biased = "stablehlo.add"(%conv_out, %bias_broadcasted_full) : (tensor<6x6x4x4xf32>, tensor<6x6x4x4xf32>) -> tensor<6x6x4x4xf32>

    // Step 3: Compute mean over spatial dims (2,3)
    %dims_to_reduce = "stablehlo.constant"() {value = dense<[2, 3]> : tensor<2xi64>} : () -> tensor<2xi64>
    %mean_sum = "stablehlo.reduce"(%biased, %c0) ({
      ^bb0(%a: tensor<6x6x4x4xf32>, %b: tensor<6x6x4x4xf32>): (tensor<6x6x4x4xf32>) {
        %sum = "stablehlo.add"(%a, %b) : (tensor<6x6x4x4xf32>, tensor<6x6x4x4xf32>) -> tensor<6x6x4x4xf32>
        "stablehlo.return"(%sum) : (tensor<6x6x4x4xf32>) -> ()
      }
    }) {dimensions = array<i64: 2, 3>} : (tensor<6x6x4x4xf32>, tensor<0x0xi64>) -> tensor<6x6x4x4xf32>
    // Divide sum by number of elements (16)
    %num_elements = "stablehlo.constant"() {value = dense<16 : i64>} : () -> tensor<i64>
    %mean = "stablehlo.divide"(%mean_sum, %num_elements) : (tensor<6x6x4x4xf32>, tensor<i64>) -> tensor<6x6x4x4xf32>

    // Step 4: Compute variance
    // Broadcast mean for subtraction
    %mean_bcast = "stablehlo.broadcast_in_dim"(%mean) {
      broadcast_dimensions = array<i64: 2, 3>
    } : (tensor<6x6x4x4xf32>) -> tensor<6x6x4x4xf32>
    %diff = "stablehlo.subtract"(%biased, %mean_bcast) : (tensor<6x6x4x4xf32>, tensor<6x6x4x4xf32>) -> tensor<6x6x4x4xf32>
    // Square differences
    %diff_squared = "stablehlo.multiply"(%diff, %diff) : (tensor<6x6x4x4xf32>, tensor<6x6x4x4xf32>) -> tensor<6x6x4x4xf32>
    // Sum squared differences
    %sum_sq_diff = "stablehlo.reduce"(%diff_squared, %c0) ({
      ^bb0(%a: tensor<6x6x4x4xf32>, %b: tensor<6x6x4x4xf32>): (tensor<6x6x4x4xf32>) {
        %sum = "stablehlo.add"(%a, %b) : (tensor<6x6x4x4xf32>, tensor<6x6x4x4xf32>) -> tensor<6x6x4x4xf32>
        "stablehlo.return"(%sum) : (tensor<6x6x4x4xf32>) -> ()
      }
    }) {dimensions = array<i64: 2, 3>} : (tensor<6x6x4x4xf32>, tensor<0x0xi64>) -> tensor<6x6x4x4xf32>
    // Variance
    %variance = "stablehlo.divide"(%sum_sq_diff, %num_elements) : (tensor<6x6x4x4xf32>, tensor<i64>) -> tensor<6x6x4x4xf32>
    // Compute stddev
    %epsilon = "stablehlo.constant"() {value = dense<1e-5 : f32>} : () -> tensor<f32>
    %variance_plus_epsilon = "stablehlo.add"(%variance, %epsilon) : (tensor<6x6x4x4xf32>, tensor<f32>) -> tensor<6x6x4x4xf32>
    %stddev = "stablehlo.sqrt"(%variance_plus_epsilon) : (tensor<6x6x4x4xf32>) -> tensor<6x6x4x4xf32>
    // Normalize
    %diff_bcast = "stablehlo.broadcast_in_dim"(%diff) {
      broadcast_dimensions = array<i64: 2, 3>
    } : (tensor<6x6x4x4xf32>) -> tensor<6x6x4x4xf32>
    %normalized = "stablehlo.divide"(%diff_bcast, %stddev) : (tensor<6x6x4x4xf32>, tensor<6x6x4x4xf32>) -> tensor<6x6x4x4xf32>
    // Divide by 'divide_by' constant
    %divide_by_const = "stablehlo.constant"() {value = dense<2.0 : f32>} : () -> tensor<f32>
    %scaled = "stablehlo.divide"(%normalized, %divide_by_const) : (tensor<6x6x4x4xf32>, tensor<f32>) -> tensor<6x6x4x4xf32>

    // Return the final tensor
    "stablehlo.return"(%scaled) : (tensor<6x6x4x4xf32>) -> ()
  }
}
