    %conv = "stablehlo.convolution"(%arg2, %arg0) {
      window_strides = dense<2: 2>,
      padding = dense<2: 1, 2: 1>,
      lhs_dilation = dense<2: 1, 3: 1, 4: 1>,
      rhs_dilation = dense<2: 1, 3: 1, 4: 1>,
      feature_group_count = 1
    } : (tensor<6x3x16x7x7xf32>, tensor<3x16x3x3x3xf32>) -> tensor<6x16x16x15x15xf32>

    // Step 2: Multiply by scalar 0.5
    %scalar_const = "constant"() {value = dense<1: 0.5> } : () -> f32
    %broadcast_scalar = "stablehlo.broadcast_in_dim"(%scalar_const) {
      broadcast_dimensions = dense<0>
    } : (f32) -> tensor<>()  // scalar tensor
    %conv_bcast = "stablehlo.broadcast_in_dim"(%conv) {
      broadcast_dimensions = dense<1, 2, 3, 4>
    } : (tensor<6x16x16x15x15xf32>) -> tensor<6x16x16x15x15xf32>
    %scaled = "stablehlo.multiply"(%conv_bcast, %broadcast_scalar) : (tensor<6x16x16x15x15xf32>, tensor<>) -> tensor<6x16x16x15x15xf32>

    // Step 3: Max Pooling with kernel size 2x2x2
    %maxpool_window = "constant"() {value = dense<3: 2> } : () -> i64
    %maxpool_padding = "constant"() {value = dense<3: 0> } : () -> i64
    %maxpool = "stablehlo.reduce_window"(%scaled) {
      window_dimensions = dense<3: 2, 4: 2, 5: 2>,
      window_strides = dense<3: 2, 4: 2, 5: 2>,
      padding = dense<3: 0, 4: 0, 5: 0>
    } : (tensor<6x16x16x15x15xf32>) -> tensor<6x16x8x7x7xf32>

    // Step 4: Global Average Pooling over spatial dims (2,3,4)
    // Compute mean over dims 2,3,4
    // First, reduce over dims 2,3,4 with mean
    // For mean, sum then divide by number of elements
    // Number of elements in spatial dims: 8*7*7=392
    %sum_spatial = "stablehlo.reduce"(%maxpool) {
      dimensions = dense<2, 3, 4>,
      to_reduce = true
    } : (tensor<6x16x8x7x7xf32>) -> tensor<6x16xf32>
    // Divide by 392
    %const_392 = "constant"() {value = dense<1: 392.0>} : () -> f32
    %avg = "stablehlo.divide"(%sum_spatial, %const_392) : (tensor<6x16xf32>, tensor<>) -> tensor<6x16xf32>

    // Step 5: Reshape to add singleton dims for final shape (6x16x1x1x1)
    %reshape_shape = "constant"() {value = dense<5: 6, 1: 16, 2: 1, 3: 1, 4: 1>} : () -> tensor<5xi64>
    %reshaped = "stablehlo.reshape"(%avg, %reshape_shape) : (tensor<6x16xf32>, tensor<5xi64>) -> tensor<6x16x1x1x1xf32>

    // Step 6: Clamp between 0 and 1
    %zero = "constant"() {value = dense<1: 0.0>} : () -> f32
    %one = "constant"() {value = dense<1: 1.0>} : () -> f32
    %clamped_min = "stablehlo.maximum"(%reshaped, %zero) : (tensor<6x16x1x1x1xf32>, tensor<>) -> tensor<6x16x1x1x1xf32>
    %clamped = "stablehlo.minimum"(%clamped_min, %one) : (tensor<6x16x1x1x1xf32>, tensor<>) -> tensor<6x16x1x1x1xf32>

    return %clamped : tensor<6x16x1x1x1xf32>
  }
