  %window_dims = "stablehlo.constant"() {value = dense<[1, 1, 4, 4]> : tensor<4xi64>} : () -> tensor<4xi64>
  // Define window strides: [1, 1, stride, stride]
  %window_strides = "stablehlo.constant"() {value = dense<[1, 1, 1, 1]> : tensor<4xi64>} : () -> tensor<4xi64>
  // Define padding: [[0,0], [0,0], [1,1], [1,1]]
  %padding_tensor = "stablehlo.constant"() {value = dense<[[0,0],[0,0],[1,1],[1,1]]]> : tensor<4x2xi64>} : () -> tensor<4x2xi64>

  // Compute the padded input
  %padded_input = "stablehlo.pad"(%arg0) {
    padding = %padding_tensor
  } : (tensor<6x7x8x8xf32>) -> tensor<6x7x10x10xf32>

  // Perform reduce_window (max pooling)
  %result = "stablehlo.reduce_window"(%padded_input, %c0) {
    ^bb0(%a: tensor<6x7x10x10xf32>, %b: tensor<6x7x10x10xf32>) -> tensor<6x7x10x10xf32> {
      %max = "stablehlo.maximum"(%a, %b) : (tensor<6x7x10x10xf32>, tensor<6x7x10x10xf32>) -> tensor<6x7x10x10xf32>
      "stablehlo.return" %max : tensor<6x7x10x10xf32>
    }
  } {
    window_dimensions = %window_dims,
    window_strides = %window_strides,
    padding = dense<[[0,0],[0,0],[1,1],[1,1]]> : tensor<4x2xi64>
  } : (tensor<6x7x10x10xf32>, tensor<f32>) -> tensor<6x7x10x10xf32>

  // Slice to remove padding and get output shape [6,7,7,7]
