// The input tensor shape: 6x7x8x8 (batch, channels, height, width)
// Output shape: 6x7x7x7 (after 2D max pooling with kernel=4, stride=1, padding=1, dilation=1)

func.func @main(%arg0: tensor<6x7x8x8xf32>) -> tensor<6x7x7x7xf32> {
  // Constants for pooling parameters
  %kernel_size = "stablehlo.constant"() {value = dense<4> : tensor<i64>} : () -> tensor<i64>
  %stride = "stablehlo.constant"() {value = dense<1> : tensor<i64>} : () -> tensor<i64>
  %padding = "stablehlo.constant"() {value = dense<1> : tensor<i64>} : () -> tensor<i64>
  %zero = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>

  // Step 1: Pad the input tensor
  // Padding: pad height and width dimensions with 1 on both sides
  // For batch and channels, no padding
  // Padding for each dimension: [[0,0], [0,0], [1,1], [1,1]]
  %padding_tensor = "stablehlo.constant"() {value = dense<[[0,0],[0,0],[1,1],[1,1]]]> : tensor<4x2xi64>}
