  // Step 2: Compute output shape
  // For each spatial dimension: floor((input + 2*padding - dilation*(kernel_size-1) -1)/stride) + 1
  // Since dilation=1, kernel=4, padding=1
  // output_height = floor((10 - 4)/1) + 1 = 7
  // output_width = same as height
  // The output shape is 6x7x7x7

  // Step 3: Prepare for reduce_window (max pooling)
  // The reduce_window operation requires the window dimensions, strides, and padding
  // window_dimensions: [1, 1, kernel_height, kernel_width]
  // strides: [1, 1, stride, stride]
  // padding: same as above

