  %reduce_padding = "stablehlo.constant"() {value = dense<[[0,0],[0,0],[0,0],[0,0]]]> : tensor<4x2xi64>

  // Step 4: Perform reduce_window (max pooling)
  %result = "stablehlo.reduce_window"(
    %padded_input,
    %zero
  ) ({
    ^bb0(%a: tensor<6x7x10x10xf32>, %b: tensor<6x7x10x10xf32>): 
      %m = "stablehlo.maximum"(%a, %b) : tensor<6x7x10x10xf32>
      "stablehlo.return" %m : tensor<6x7x10x10xf32>
  }) {
    window_dimensions = %window_dims,
    window_strides = %strides,
    padding = %reduce_padding
  } : (tensor<6x7x10x10xf32>, tensor<f32>) -> tensor<6x7x7x7xf32>

  // The output shape of reduce_window is 6x7x7x7, matching the desired output shape
  // Return the result
  return %result : tensor<6x7x7x7xf32>
}
