func.func @main(%x: tensor<6xf32>) -> tensor<16xf32> {
  %zero = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
  %padding_value = %zero : tensor<f32>
  // Define edge_padding_low: insert zeros before each element
  // For each element, we want to position it at index 3*i, so:
  // edge_padding_low = [0, 2] (for the first element), [3, 2], ..., but since padding is per dimension, and we want to insert zeros between elements,
  // we can pad at the start with 0, then at the end with 0, and specify interior padding.
  // But since the padding operation in StableHLO applies to the entire tensor, we can pad with zeros at the start and end, and specify interior padding.
  // To get zeros between elements, set interior_padding to 2.
  // shape of input: [6]
  // shape of output: [16]
  // shape calculation:
  // shape_out = edge_padding_low + shape_in + max(shape_in - 1, 0) * interior_padding + edge_padding_high
  // Let's set edge_padding_low = [0], edge_padding_high = [0]
  // interior_padding = [2]
  // So shape_out = 0 + 6 + (6-1)*2 + 0 = 6 + 10 = 16, as desired.
  %edge_padding_low = array<i64: 0>
  %edge_padding_high = array<i64: 0>
  %interior_padding = array<i64: 2>
  %padded = "stablehlo.pad"(%x, %padding_value) {
    edge_padding_low = %edge_padding_low,
    edge_padding_high = %edge_padding_high,
    interior_padding = %interior_padding
  } : (tensor<6xf32>, tensor<f32>) -> tensor<16xf32>
  return %padded : tensor<16xf32>
}
