// StableHLO program to compute, for each row, the count of elements > 0
module {
  func.func @main(%x: tensor<8x3xf32>) -> tensor<8xi32> {
    // Step 1: Create a constant tensor of zeros for comparison
    %zero = stablehlo.constant dense<0.0> : tensor<f32>
    // Step 2: Compare each element of x with zero to get a boolean tensor
    %cmp = "stablehlo.compare"(%x, %zero) {comparison_direction = #stablehlo<comparison_direction LT>, compare_type = #stablehlo<compare_type FLOAT>} : (tensor<8x3xf32>, tensor<f32>) -> tensor<8x3xi1>
    // Step 3: Convert boolean tensor to i32 (true -> 1, false -> 0)
    %one = stablehlo.constant dense<1> : tensor<i32>
    %zero_i32 = stablehlo.constant dense<0> : tensor<i32>
    // Use select to convert boolean to int: if true then 1 else 0
    // But StableHLO does not have select, so we can do: convert boolean to i32 by multiplying with 1
    // First, convert boolean to i32: true -> 1, false -> 0
    // Since boolean is tensor<8x3xi1>, convert to i32 by multiplying with 1
    %cmp_i32 = "stablehlo.convert"(%cmp) : (tensor<8x3xi1>) -> tensor<8x3xi32>
    // Step 4: Sum over the last dimension (j) to count how many are > 0 per row
    // Initialize reduction with zeros
    %init = stablehlo.constant dense<0> : tensor<i32>
    // Define reduction body
    ^bb0(%a: tensor<i32>, %b: tensor<i32>): (tensor<i32>) {
      %sum = "stablehlo.add"(%a, %b) : (tensor<i32>, tensor<i32>) -> tensor<i32>
      "stablehlo.return"(%sum) : (tensor<i32>) -> ()
    }
    // Perform reduce over dimension 1 (columns)
    %result = "stablehlo.reduce"(%cmp_i32, %init) ({
      ^bb0(%a: tensor<i32>, %b: tensor<i32>): (tensor<i32>) {
        %sum = "stablehlo.add"(%a, %b) : (tensor<i32>, tensor<i32>) -> tensor<i32>
        "stablehlo.return"(%sum) : (tensor<i32>) -> ()
      }
    }) {dimensions = array<i64: 1>} : (tensor<8x3xi1>, tensor<i32>) -> tensor<8xi32>
    // Return the result
    return %result : tensor<8xi32>
  }
}
