    // Bias addition
    %bias_bcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = dense<0> : tensor<1>} : tensor<16xf32>
    %conv_bias = "stablehlo.add"(%conv, %bias_bcast) : tensor<16x8x3x3xf32>

