    %diff = "stablehlo.subtract"(%conv_bias, "stablehlo.broadcast_in_dim"(%mean, shape(%conv_bias), dense<0,1,2,3>)) : tensor<16x8x3x3xf32>
    %squared_diff = "stablehlo.multiply"(%diff, %diff) : tensor<16x8x3x3xf32>
    %var = "stablehlo.reduce"(%squared_diff, "stablehlo.reduce-mean", %axes) {keep_dims = true} : tensor<16x8x1x1xf32>
