// StableHLO program implementing the forward pass of the described PyTorch model
func.func @main(%arg0: tensor<1x16x1x1xf32>, %arg1: tensor<16x16xf32>, %arg2: tensor<16xf32>, %arg3: tensor<16xf32>, %arg4: tensor<16xf32>, %arg5: tensor<16x16xf32>) -> tensor<1x16x16x1xf32> {
  // Step 1: GEMM (Linear layer)
  // %a = broadcast %arg0 to shape compatible for matmul
  %b = "stablehlo.transpose"(%arg1) {permutation = array<i64: 1, 0>} : (tensor<16x16xf32>) -> tensor<16x16xf32>
  // Since %arg0 is [1,16,1,1], reshape to [16]
  %arg0_reshaped = "stablehlo.reshape"(%arg0) : (tensor<1x16x1x1xf32>) -> tensor<16xf32>
  // Perform dot_general: [16] x [16,16] -> [16]
  %gemm_result = "stablehlo.dot_general"(%arg0_reshaped, %arg1) {
    dot_dimension_numbers = #stablehlo.dot<lhs_batching_dimensions = [], rhs_batching_dimensions = [], lhs_contracting_dimensions = [0], rhs_contracting_dimensions = [0]>
  } : (tensor<16xf32>, tensor<16x16xf32>) -> tensor<16xf32>
  // Reshape result to [1,16,1,1]
  %gemm_reshaped = "stablehlo.reshape"(%gemm_result) : (tensor<16xf32>) -> tensor<1x16x1x1xf32>
  // Broadcast to match input shape for subsequent ops
  %gemm_broadcasted = "stablehlo.broadcast_in_dim"(%gemm_reshaped) {
    broadcast_dimensions = array<i64: 0, 1, 2, 3>
  } : (tensor<1x16x1x1xf32>) -> tensor<1x16x1x1xf32>

  // Step 2: GroupNorm
  // %gn_weight and %gn_bias are %arg3 and %arg4 respectively, shape [16]
  // Broadcast %arg5 (input) to shape [1,16,1,1]
  %input_broadcasted = "stablehlo.broadcast_in_dim"(%arg5) {
    broadcast_dimensions = array<i64: 0, 1, 2, 3>
  } : (tensor<16x16xf32>) -> tensor<1x16x1x1xf32>
  // Add the GEMM result to input (element-wise)
  %add_gemm_input = "stablehlo.add"(%gemm_broadcasted, %input_broadcasted) : (tensor<1x16x1x1xf32>, tensor<1x16x1x1xf32>) -> tensor<1x16x1x1xf32>
  // Reshape %arg5 to [16,16] for normalization
  %arg5_reshaped = "stablehlo.reshape"(%arg5) : (tensor<16x16xf32>) -> tensor<16x16xf32>
  // For simplicity, assume batch stats are computed as mean and variance over batch dimension (0)
  // Compute mean over batch (dimension 0)
  %mean_sum = "stablehlo.reduce"(%arg5_reshaped, %c0) ({
    ^bb0(%a: tensor<16x16xf32>, %b: tensor<16x16xf32>): tensor<16x16xf32> {
      %s = "stablehlo.add"(%a, %b) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
      "stablehlo.return"(%s) : (tensor<16x16xf32>) -> ()
    }
  }) : (tensor<16x16xf32>, tensor<f32>) -> tensor<16x16xf32>
  // Divide sum by batch size (16) to get mean
  %batch_size_const = "stablehlo.constant"() {value = dense<16> } : () -> tensor<()>
  %mean = "stablehlo.divide"(%mean_sum, %batch_size_const) : (tensor<16x16xf32>, tensor<()>) -> tensor<16x16xf32>
  // Broadcast mean to shape [1,16,1,1]
  %mean_broadcasted = "stablehlo.broadcast_in_dim"(%mean) {
    broadcast_dimensions = array<i64: 0, 1, 2, 3>
  } : (tensor<16x16xf32>) -> tensor<1x16x1x1xf32>
  // Compute variance: (x - mean)^2, then mean over batch
  %x_minus_mean = "stablehlo.subtract"(%arg5, %mean_broadcasted) : (tensor<16x16xf32>, tensor<1x16x1x1xf32>) -> tensor<16x16xf32>
  %x_minus_mean_sq = "stablehlo.multiply"(%x_minus_mean, %x_minus_mean) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
  // Sum over batch
  %var_sum = "stablehlo.reduce"(%x_minus_mean_sq, %c0) ({
    ^bb0(%a: tensor<16x16xf32>, %b: tensor<16x16xf32>): tensor<16x16xf32> {
      %s = "stablehlo.add"(%a, %b) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
      "stablehlo.return"(%s) : (tensor<16x16xf32>) -> ()
    }
  }) : (tensor<16x16xf32>, tensor<f32>) -> tensor<16x16xf32>
  // Divide by batch size to get variance
